						</div>
				</div>
				<div class="elementor-element elementor-element-f9a8389 elementor-widget elementor-widget-text-editor" data-id="f9a8389" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong>Không. Không đời nào. Hmm, nó hay đó nhưng chưa phải bây giờ.</strong></p>
<p>Một nhân viên, việc thực hiện công việc, cần đảm bảo được sự cho phép—khởi động chiến lược mới, cộng tác với bộ phận khác, đi nghỉ.</p>
<p>Đó là một vấn đề khi&nbsp;<strong>câu trả lời mặc định của sếp</strong>&nbsp;là:&nbsp;<strong>KHÔNG</strong>.</p>
<p>Tất cả chúng ta đã ở đó. Bạn có một ý tưởng tuyệt vời, một tầm nhìn về cách chuyển đổi bộ phận hoặc sự nghiệp của bạn, nhưng người quản lý của bạn dường như là người gác cổng vĩnh viễn cho chữ ‘Không’.</p>
<p><em>Nó có thể vô cùng khó chịu, cản trở sự phát triển của chúng ta và khiến chúng ta chán nản.</em></p>
<p>Kerry Flynn Barrett, một nhà tư vấn nhân sự từng có một ông chủ luôn cản trở nỗ lực của cô để đảm nhận những dự án lớn hơn và có nhiều trách nhiệm hơn, cho biết: “Điều đó đã cản trở sự nghiệp của tôi”.</p>
<p>Mãi cho đến khi một người quản lý cởi mở hơn tiếp quản nhóm thì Flynn Barrett mới có thể vươn lên. Khi nhìn lại, cô tự hỏi liệu mình có thể thuyết phục được ông chủ ban đầu bằng cách sử dụng nhiều dữ liệu hơn để hỗ trợ các đề xuất của mình hay khiến ông chủ hỏi ý kiến trong bữa trưa và cuộc trò chuyện ấm áp hay không.</p>
<p>Tất cả chúng ta đều có chung một đặc điểm – ác cảm khi nghe “Không”. Những lời từ chối thường tác động đến cá nhân chúng ta, khiến chúng ta cảm thấy bị coi thường hoặc tin rằng sự nghiệp của mình đã kết thúc. Đáp lại, chúng ta có thể thấy mình tức giận tại bàn làm việc hoặc đối đầu một cách bốc đồng với sếp, điều này thường dẫn đến sự hối tiếc.</p>
<p>Tuy nhiên, như William Ury, người đồng sáng lập chương trình đàm phán của Đại học Harvard, đã chỉ ra, trở ngại lớn nhất để đạt được điều chúng ta mong muốn thường là chính bản thân chúng ta.</p>
<p>Ury đề xuất một cách tiếp cận khác. Sau khi nghe ‘Không’, hãy thể hiện sự đồng cảm và tò mò thay vì cáu kỉnh. Hãy tưởng tượng bạn và sếp của bạn là những diễn viên trong một vở kịch. Trả lời bằng “Tôi hiểu” và đặt câu hỏi “nếu như”. Ví dụ: “Điều gì sẽ xảy ra nếu chúng ta thử áp dụng nó vào quý tới? Điều gì sẽ xảy ra nếu hoạt động tiếp thị đặt nền móng cho khách hàng?” Để khám phá lý do thực sự đằng sau câu nói ‘Không’ của sếp, hãy thử “Tại sao không?” với giọng điệu tò mò.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-cbb149b elementor-widget elementor-widget-image" data-id="cbb149b" data-element_type="widget" data-widget_type="image.default">
				<div class="elementor-widget-container">
															<img loading="lazy" decoding="async" width="800" height="120" src="https://media.huynhhieutravel.com/line.png" class="attachment-large size-large wp-image-12946" alt="" srcset="https://media.huynhhieutravel.com/line.png 1280w, https://media.huynhhieutravel.com/line-768x115.png 768w" sizes="(max-width: 800px) 100vw, 800px" />															</div>
				</div>
				<div class="elementor-element elementor-element-8e74077 elementor-widget elementor-widget-heading" data-id="8e74077" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Khi Sếp mắc kẹt ở điểm dừng KHÔNG</h2>				</div>
				</div>
				<div class="elementor-element elementor-element-4822121 elementor-widget elementor-widget-text-editor" data-id="4822121" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Hiểu lý do tại sao các nhà quản lý của chúng ta dường như mặc định là &#8216;Không&#8217; là điều quan trọng trong nỗ lực lật ngược tình thế của chúng ta.</p><p>Có thể người quản lý của bạn <strong>vốn đã bi quan hoặc có hiểu biết sâu sắc hơn</strong> về những hạn chế về ngân sách hiện tại của công ty. Họ cũng có thể lo lắng rằng khi nói &#8216;Có&#8217;, bạn sẽ nổi trội hơn họ hoặc người quản lý của họ sẽ phản ứng tiêu cực với quyết định của họ. <strong>Đôi khi đó chỉ là sự mệt mỏi</strong>; công việc hàng ngày ảnh hưởng đến mọi người.</p><p>Trong những tình huống này, Tom Krouse, Giám đốc điều hành của Donatos Pizza, một chuỗi cửa hàng khá lớn với 461 địa điểm có trụ sở tại Columbus, Ohio, đề xuất một cách tiếp cận chiến lược: chia đề xuất của bạn thành 2 giai đoạn. <strong>Giai đoạn đầu tiên xoay quanh việc đặt câu hỏi có-không</strong> mà gần như không thể từ chối. Nó phải rộng, không mang tính quy định và liên kết với mục tiêu hoặc thách thức rộng lớn hơn của công ty.</p><blockquote><p>Nhóm điều hành và đổi mới của Krouse đã sử dụng chiến lược này khi họ gặp phải những thách thức về lao động trong công ty. Chi phí tiền lương ngày càng tăng và công nhân không muốn thực hiện một số nhiệm vụ làm bánh pizza nhất định. Thay vì đề xuất một giải pháp cụ thể ngay lập tức, họ tìm kiếm sự thừa nhận của Krouse rằng cần phải làm gì đó. “Tôi không thể tranh cãi với điều đó,” Krouse thừa nhận.</p></blockquote><p>Nếu họ ngay lập tức đề xuất tự động hóa quy trình làm bánh pizza, Krouse thừa nhận rằng ông sẽ phản đối vì sợ điều đó sẽ làm hoen ố tình cảm con người trân quý của công ty. Tuy nhiên, cách tiếp cận chậm rãi và có chừng mực cho phép anh ấy dễ tiếp thu hơn. Vài tháng sau, khi nhóm quay trở lại để trình diễn một chiếc máy có thể làm nước sốt cho bánh pizza chỉ trong 7 giây, Krouse đã rất cởi mở với ý tưởng này.</p><p>Như ông phản ánh, cách tiếp cận chậm rãi này đóng một vai trò quan trọng trong việc ngăn chặn những quyết định bốc đồng và mang tính cảm xúc. Nó cho phép có thời gian để xem xét và cuối cùng dẫn đến những kết quả có tính xây dựng và chu đáo hơn.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-303073e elementor-widget elementor-widget-image" data-id="303073e" data-element_type="widget" data-widget_type="image.default">
				<div class="elementor-widget-container">
															<img loading="lazy" decoding="async" width="800" height="120" src="https://media.huynhhieutravel.com/line.png" class="attachment-large size-large wp-image-12946" alt="" srcset="https://media.huynhhieutravel.com/line.png 1280w, https://media.huynhhieutravel.com/line-768x115.png 768w" sizes="(max-width: 800px) 100vw, 800px" />															</div>
				</div>
				<div class="elementor-element elementor-element-2a2254a elementor-widget elementor-widget-heading" data-id="2a2254a" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Cuộc họp trước Cuộc họp</h2>				</div>
				</div>
				<div class="elementor-element elementor-element-63ac3ef elementor-widget elementor-widget-text-editor" data-id="63ac3ef" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Một trong những vũ khí mạnh mẽ nhất chống lại <strong>chữ ‘Không’ kiên cường</strong> là sự chuẩn bị. Peter Mulford, Giám đốc Đổi mới của công ty tư vấn chiến lược BTS, đưa ra một chiến lược có thể xoay chuyển tình thế theo hướng có lợi cho bạn. Ông gọi đó là <strong>“cuộc họp trước cuộc họp” và đó là một chiến thuật có thể thay đổi cuộc chơi</strong>.</p><p>Trước khi bạn thu hút sự chú ý của sếp trong một cuộc họp quan trọng, hãy bắt đầu màn dạo đầu thiết yếu này. Chìa khóa chính là “bản lý lịch ý tưởng” – một tài liệu dài một trang đóng vai trò như một tiền thân đầy sức mạnh. Trong hồ sơ ngắn gọn này, bạn trình bày một trường hợp thuyết phục, được chứng minh bằng bằng chứng và cung cấp một bức tranh rõ ràng về đề xuất của bạn sẽ tác động đến ai.</p><blockquote><p>Nhưng đây là bí quyết: sau khi gửi bản ghi nhớ này, hãy lôi kéo sếp của bạn vào một cuộc trò chuyện quan trọng. Hãy đặt câu hỏi có thể mở ra những cánh cửa và thay đổi quan điểm: &#8220;Điều gì đúng thì bạn mới thực sự hào hứng với điều này?&#8221;</p></blockquote><p>Hơn nữa, <strong>đừng để sếp của bạn không biết gì trong suốt quá trình</strong>. Đặt điểm kiểm tra, chia đề xuất của bạn thành các giai đoạn có thể quản lý được.</p><p><em>Ví dụ: nếu sếp của bạn cần thuyết phục rằng có nhu cầu thực sự cho dự án kinh doanh mà bạn đề xuất, hãy cân nhắc việc yêu cầu 5.000 USD để một công ty tiếp thị ước tính cơ sở khách hàng. Cách tiếp cận này ít khó khăn hơn nhiều so với việc yêu cầu trả trước 300.000 USD để tài trợ cho toàn bộ dự án.</em></p><p>Bằng cách áp dụng cách tiếp cận chiến lược này, bạn chứng tỏ rằng bạn không cố gắng ép buộc một quyết định. Thay vào đó, bạn thực sự đang tìm kiếm sự thật và hành động vì lợi ích tốt nhất của công ty. Sếp sẽ đánh giá cao sự tỉ mỉ và cống hiến của bạn trong việc tìm ra con đường phù hợp nhất phía trước.</p><p>Bằng cách này, bạn không chỉ làm cho đề xuất của mình trở nên dễ chấp nhận hơn mà còn đặt nền tảng cho mối quan hệ làm việc hợp tác và cùng có lợi hơn.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-0fd9768 elementor-widget elementor-widget-image" data-id="0fd9768" data-element_type="widget" data-widget_type="image.default">
				<div class="elementor-widget-container">
															<img loading="lazy" decoding="async" width="800" height="120" src="https://media.huynhhieutravel.com/line.png" class="attachment-large size-large wp-image-12946" alt="" srcset="https://media.huynhhieutravel.com/line.png 1280w, https://media.huynhhieutravel.com/line-768x115.png 768w" sizes="(max-width: 800px) 100vw, 800px" />															</div>
				</div>
				<div class="elementor-element elementor-element-aa8f2d8 elementor-widget elementor-widget-heading" data-id="aa8f2d8" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Trở thành người đáng tin cậy</h2>				</div>
				</div>
				<div class="elementor-element elementor-element-45c4e7c elementor-widget elementor-widget-text-editor" data-id="45c4e7c" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Trong nỗ lực vượt qua câu trả lời &#8216;Không&#8217; không ngừng nghỉ, việc thiết lập niềm tin và kiến thức chuyên môn là một chiến lược then chốt. Michael Quinn, Giám đốc điều hành của Minor Nobles, một công ty chuyên đào tạo các chuyên gia trong công ty về cách thuyết trình và thuyết trình hiệu quả, đưa ra những lời khuyên có giá trị.</p><p>Để có được sự tin tưởng và ảnh hưởng, hãy bắt đầu bằng cách khẳng định mình là chuyên gia trong lĩnh vực của bạn. Điều quan trọng là sự nhất quán và kiên trì. Gửi liên tục các liên kết, bài viết và thông tin chi tiết liên quan đến miền của bạn trong nhiều tuần. Chia sẻ kiến thức của bạn về các chủ đề bạn quan tâm và phù hợp, dần dần nhưng chắc chắn sẽ xây dựng được danh tiếng của bạn với tư cách là nguồn chuyên môn đáng tin cậy.</p><p>Khi đến lúc trình bày ý tưởng đột phá của riêng bạn, bạn đã có được sự tin tưởng và tín nhiệm, giúp sếp dễ dàng xem xét đề xuất của bạn một cách nghiêm túc hơn.</p><p>Một chiến lược hiệu quả khác, theo gợi ý của Quinn, là xác định xem sếp của bạn tin tưởng ai nhất. Bán trước ý tưởng của bạn cho người đó, tìm kiếm sự hướng dẫn của họ và kết hợp phản hồi của họ vào đề xuất cuối cùng của bạn. Bằng cách đó, bạn đảm bảo rằng mình đã có được một đồng minh đắc lực khi sếp tìm đến người bạn tâm giao của họ để xin lời khuyên.</p><p>Điều quan trọng là phải nói rõ rằng ý định của bạn không phải là đi sau lưng sếp mà là tìm kiếm lời khuyên ban đầu, củng cố tinh thần cộng tác và hợp tác.</p><p>Amy Gallo, tác giả của cuốn sách &#8220;Hòa nhập&#8221;, một cuốn sách cung cấp những hiểu biết sâu sắc về cách quản lý những đồng nghiệp khó tính, chia sẻ kinh nghiệm của bản thân với một ông chủ có phản ứng tức thời là &#8216;Không&#8217; trước những ý tưởng tuyệt vời, chỉ để sau đó thực hiện chúng. Ban đầu khó chịu, Gallo và các đồng nghiệp của cô cuối cùng nhận ra rằng ít nhất ý tưởng của họ đã được thực hiện.</p><p>Đáp lại, Gallo đề xuất một sự thay đổi chiến lược trong ngôn ngữ. Thay vì sử dụng &#8220;tôi&#8221;, hãy chọn &#8220;chúng ta&#8221; khi giới thiệu ý tưởng với một ông chủ không an toàn. Sự thay đổi đơn giản này có thể truyền tải ý thức cộng tác và chia sẻ trách nhiệm, khiến đề xuất của bạn trở nên dễ tiếp cận hơn.</p><p>Cuối cùng, đừng chán nản vì những điều tiêu cực ban đầu. Như Gallo đã chỉ ra một cách khôn ngoan, “Không” không phải lúc nào cũng là lời cuối cùng. Với sự kiên trì và cách tiếp cận đúng đắn, bạn có thể biến nó thành cơ hội cho một cuộc trò chuyện hiệu quả và mang tính thay đổi.</p><p>Bằng cách kết hợp các chiến lược này, bạn không chỉ nâng cao khả năng điều hướng nơi làm việc mà còn mở đường cho một môi trường hợp tác và đổi mới hơn.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-a5eaa29 elementor-widget elementor-widget-text-editor" data-id="a5eaa29" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<blockquote><p>Bối cảnh nơi làm việc đã phát triển đáng kể, nhấn mạnh đến tính đa dạng, công bằng và hòa nhập (DEI). Tuy nhiên, đúng là trong bối cảnh này, &#8220;không&#8221; đôi khi có thể được xem là câu trả lời dễ dàng nhất và phù hợp nhất về mặt pháp lý. Nỗi sợ hãi và sự tự bảo vệ thường ăn sâu vào tâm trí các nhà quản lý.</p><p>Cần lưu ý rằng cách sếp đưa ra câu trả lời &#8220;không&#8221; có thể tạo ra sự khác biệt đáng kể. Mặc dù một số người có thể đánh giá cao người quản lý có thể nói &#8220;có, nhưng&#8230;&#8221; thay vì nói &#8220;không&#8221; thẳng thừng, nhưng điều cần thiết là phải nhận ra rằng tác động đối với nhân viên có thể tương tự. Trong trường hợp này, cách tiếp cận cũng quan trọng không kém chính phản ứng. Một người quản lý giỏi thực sự nên tìm cách làm việc cùng nhau để sàng lọc các ý tưởng và đề xuất thay vì loại bỏ chúng hoàn toàn.</p><p>Tóm lại, nơi làm việc là một hệ sinh thái phức tạp, nơi lợi ích của nhân viên và nhu cầu của tổ chức phải cùng tồn tại. Các nhà lãnh đạo nên cố gắng tỏ ra đồng cảm và cởi mở, nhận ra tiềm năng trong ý tưởng của nhân viên. Mặt khác, nhân viên nên tham gia một cách mang tính xây dựng, không chỉ với những đề xuất của họ mà còn với những mối quan tâm và thách thức mà cấp trên của họ phải đối mặt.</p><p>Bằng cách thúc đẩy một môi trường hiểu biết, tôn trọng và hợp tác lẫn nhau, chúng ta có thể vượt qua những giới hạn của việc “không” và mở đường cho những nơi làm việc sáng tạo, hiệu quả và hài hòa hơn. Đó là một hành trình chung hướng tới sự tiến bộ, trong đó cả ông chủ và nhân viên đều đóng vai trò quan trọng trong việc lèo lái con tàu hướng tới thành công.</p></blockquote>								</div>
				</div>
					</div>
				</div>
				</div>
		', 'Bạn có những ý tưởng tuyệt vời. Bạn trình bày nó lên người quản lý. Và nó luôn luôn là câu trả lời KHÔNG! Đã đến lúc thay đổi chiến lược, để nhận được các kết quả tốt hơn. Home Không. Không đời nào. Hmm, nó hay đó nhưng chưa phải bây giờ. Một nhân [&hellip;]', 12937, 'post', '2024-09-06 21:32:43', '2024-09-06 21:34:43');
