INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (12129, 'Kỹ thuật Pomodoro: Phương pháp tập trung hiệu quả', 'ky-thuat-pomodoro', '
<p>Kỹ thuật Pomodoro là một phương pháp quản lý thời gian dựa trên việc tập trung làm việc kéo dài 25 phút và nghỉ giải lao 5 phút.&nbsp;Thời gian nghỉ dài hơn, thường là 15 đến 30 phút, được thực hiện sau 4 khoảng thời gian làm việc liên tiếp.</p>



<p><strong>Mỗi khoảng thời gian làm việc gọi là&nbsp;pomodoro, từ tiếng Ý có nghĩa là cà chua (số nhiều: <em>pomodori</em>).</strong></p>



<h2 class="wp-block-heading">Lịch sử hình thành</h2>



<p>Nhà phát triển và doanh nhân Francesco Cirillo&nbsp;<a href="https://francescocirillo.com/products/the-pomodoro-technique" target="_blank" rel="noreferrer noopener">đã tạo ra Kỹ thuật Pomodoro</a>&nbsp;vào cuối những năm 1980, khi ông còn là sinh viên đại học và sử dụng đồng hồ bấm giờ trong bếp hình quả cà chua để sắp xếp lịch học của mình.</p>



<p>Lúc đầu, ông ấy thử nghiệm các khoảng thời gian làm việc khác nhau, bắt đầu từ 2 phút và kéo dài lên đến 1 giờ;&nbsp;ông ấy nhanh chóng nhận ra rằng khoảng thời gian này quá dài để có thể tập trung vào một nhiệm vụ.&nbsp;Ông ấy chọn pomodori kéo dài 25 phút là thời gian tối ưu cho nhu cầu của mình.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>Từ trải nghiệm này, Cirillo nhận ra rằng thời gian có thể biến thành đồng minh chứ không phải là nguồn gốc gây lo lắng.</p>
</blockquote>



<p>Kỹ thuật Pomodoro về cơ bản huấn luyện mọi người tập trung vào nhiệm vụ tốt hơn bằng cách giới hạn khoảng thời gian họ cố gắng duy trì sự tập trung đó và đảm bảo có những khoảng thời gian nghỉ ngơi để phục hồi sau nỗ lực.</p>



<p>Phương pháp này cũng giúp họ vượt qua xu hướng trì hoãn hoặc&nbsp;làm nhiều việc cùng lúc, cả hai đều làm giảm&nbsp;năng suất.</p>



<h2 class="wp-block-heading">Kỹ thuật Pomodoro đòi hỏi gì?</h2>



<p>Kỹ thuật Pomodoro cũng có thể giúp các cá nhân phát triển thói quen làm việc hiệu quả hơn.&nbsp;Thông qua&nbsp;việc quản lý thời gian&nbsp;hiệu quả, họ có thể làm được nhiều việc hơn trong thời gian ngắn hơn, đồng thời đạt được cảm giác hoàn thành công việc và giảm nguy cơ kiệt sức.</p>



<p>Để đạt được mục tiêu này, Kỹ thuật Pomodoro bao gồm 5 quy trình tăng dần để giúp phát triển mối quan hệ có ý thức và hiệu quả với thời gian:</p>



<ul class="wp-block-list">
<li><strong>Quy trình nội bộ của Pomodoro.&nbsp;</strong>Phát triển mối quan hệ hiệu quả với thời gian để nâng cao năng suất.</li>



<li><strong>Quy trình cốt lõi của Pomodoro.&nbsp;</strong>Tập trung vào các nhiệm vụ để đạt được mục tiêu với ít nỗ lực hơn.</li>



<li><strong>Quy trình hàng ngày của Pomodoro.&nbsp;</strong>Thiết lập thói quen hàng ngày, cải thiện quy trình làm việc hàng ngày và hoàn thành nhiều nhiệm vụ hiệu quả hơn.</li>



<li><strong>Quy trình hàng tuần của Pomodoro.&nbsp;</strong>Thiết lập thói quen hàng tuần, sắp xếp thời gian hiệu quả hơn và đạt được nhiều mục tiêu.</li>



<li><strong>Quy trình của nhóm Pomodoro.&nbsp;</strong>Học cách áp dụng Kỹ thuật Pomodoro vào môi trường nhóm.</li>
</ul>



<p>Quy trình cốt lõi đóng vai trò là nền tảng để đạt được Kỹ thuật Pomodoro một cách bền vững.&nbsp;Nó xác định 5 bước sau để tập trung vào các nhiệm vụ trước mắt trong suốt cả ngày:</p>



<ol class="wp-block-list">
<li>Chọn nhiệm vụ cho pomodoro hiện tại.</li>



<li>Đặt bộ hẹn giờ thành 25 phút.</li>



<li>Thực hiện nhiệm vụ cho đến khi đồng hồ kêu, sau đó ghi lại việc hoàn thành pomodoro.</li>



<li>Nghỉ ngơi một lát;&nbsp;bắt đầu với 5 phút nhưng hãy biết rằng nó có thể chỉ là 2 phút.</li>



<li>Sau 4 pomodori, hãy nghỉ ngơi lâu hơn;&nbsp;điều này thường là 15 đến 30 phút.</li>
</ol>



<p>Đối với mỗi pomodoro, hãy dành thời gian để tóm tắt và xem xét để giúp chuyển đổi từ pomodoro này sang pomodoro khác một cách liền mạch.&nbsp;Quan trọng hơn, hãy thực hiện mọi bước cần thiết để tập trung vào nhiệm vụ trong thời gian pomodoro và tránh bị gián đoạn.</p>



<p>Các cá nhân cần bảo vệ pomodoro của mình khỏi những phiền nhiễu bên trong và bên ngoài.&nbsp;Tránh kiểm tra email, tài khoản mạng xã hội, dự báo thời tiết, các kênh tin tức hoặc bất kỳ hoạt động giải trí nào khác có thể khiến bạn mất tập trung khỏi nhiệm vụ hiện tại.</p>



<p>Các cách triển khai khác nhau của Kỹ thuật Pomodoro sử dụng các khoảng thời gian khác nhau cho các phân đoạn nhiệm vụ và nghỉ giải lao.&nbsp;Trong thời gian nghỉ giải lao, cá nhân nên chọn một hoạt động tương phản với nhiệm vụ.</p>



<p>Ví dụ, một người nào đó làm việc bên&nbsp;máy tính&nbsp;nên rời khỏi bàn làm việc và thực hiện một số hoạt động thể chất.</p>



<p><strong>Công cụ sử dụng Pomodoro online: <a href="https://pomofocus.io/">Công cụ bấm giờ Promofocos</a>.</strong></p>
', 'Kỹ thuật Pomodoro là phương pháp quản lý thời gian tập trung làm việc kéo dài 25 phút và nghỉ giải lao 5 phút. Tận dụng tối đa hiệu quả học tập.', NULL, 'post', '2024-09-04 21:18:16', '2024-09-06 21:04:38');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (12129, 434);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (12126, 'Yêu cầu đánh giá cao là gì? (Định nghĩa, ví dụ và mô hình)', 'mo-hinh-yeu-cau-danh-gia-cao', '
<p>Trong một môi trường kinh doanh toàn cầu không thể đoán trước, việc tiếp cận chiến lược với những mục tiêu cụ thể đã có sẵn trong đầu là điều rất hấp dẫn.</p>



<p>Thông thường, đây là những điều <strong>tập trung vào vấn đề</strong> và nhằm <strong>mục đích giảm thiểu các mối đe dọa</strong>.</p>



<p>Các doanh nghiệp thường tập trung vào những gì không hiệu quả và áp dụng tư duy &#8216;nguyên nhân gốc rễ&#8217;, chỉ để thấy mình phải đối mặt với một loạt các câu hỏi khác nhau nhưng có liên quan đến nhau.</p>



<p>Những câu hỏi như “Làm cách nào chúng ta có thể khắc phục tình trạng thiếu gắn kết?“ “Chúng ta phải làm gì với động lực thấp?“ “Hoặc, tại sao mọi người lại không đoàn kết vì mục tiêu chung?”</p>



<p>Mô hình tìm hiểu đánh giá cao là một trong những phương pháp tiếp cận tổ chức tích cực quan trọng đối với sự phát triển và học tập tập thể.</p>



<p>Ở đây, chúng ta xem xét làm thế nào nó đã phát triển thành một trong những phong trào có ảnh hưởng nhất đối với sự phát triển tổ chức tích cực trong những thập kỷ gần đây.</p>



<h2 class="wp-block-heading">Yêu cầu đánh giá cao là gì?</h2>



<p>Điều tra đánh giá cao (Appreciative Inquiry &#8211; AI) là một cách tiếp cận hợp tác, dựa trên thế mạnh để thay đổi trong các tổ chức và các hệ thống con người khác.&nbsp;Do đó, thuật ngữ &#8216;Yêu cầu đánh giá cao&#8217; được sử dụng để chỉ cả hai:</p>



<ul class="wp-block-list">
<li>Mô hình AI – bản thân nó liên quan đến các nguyên tắc và lý thuyết đằng sau cách tiếp cận thay đổi dựa trên điểm mạnh;&nbsp;Và</li>



<li>Phương pháp và sáng kiến ​​AI – là các kỹ thuật và bước vận hành cụ thể được sử dụng để mang lại sự thay đổi tích cực trong hệ thống (Davidcooperrider.com, 2019).</li>
</ul>



<h3 class="wp-block-heading">Các khái niệm chính trong AI</h3>



<p>Ý tưởng cơ bản đằng sau AI là theo thời gian, việc các tổ chức tiếp cận sự thay đổi và tăng trưởng từ góc độ giải quyết vấn đề ngày càng trở nên phổ biến.</p>



<p>Khi các công ty đặt mục tiêu nâng cao hiệu quả, tồn tại, hoạt động tốt hơn và tăng cường khả năng cạnh tranh, những người ủng hộ AI cho rằng đã có sự nhấn mạnh quá mức không lành mạnh vào việc “sửa chữa những gì sai” &#8211; một cách tiếp cận dựa trên thâm&nbsp;hụt.</p>



<p>AI nảy sinh như một thách thức đối với những giả định đã ăn sâu này và đề xuất rằng thay vào đó, các tổ chức có thể hưởng lợi từ cái được gọi là cách tiếp cận&nbsp;dựa trên điểm mạnh&nbsp;hoặc&nbsp;khẳng định&nbsp;(Hammond, 2013).</p>



<p>Ngược lại, cách tiếp cận khẳng định này giả định rằng mỗi hệ thống của con người đều có một&nbsp;<em>điểm mạnh cốt lõi tích cực</em>.</p>



<p>Cốt lõi tích cực này không khác nhiều so với cách chúng ta nhìn nhận sức mạnh của tổ chức trong các tài liệu quản lý thông thường.&nbsp;Về bản chất (và được các tác giả diễn giải một cách lỏng lẻo), chúng có thể bao gồm (Cooperrider &amp; Whitney, 2005):</p>



<ul class="wp-block-list">
<li>Các giá trị, niềm tin và khả năng của tổ chức chúng ta khi nó &#8216;ở trạng thái tốt nhất&#8217;;&nbsp;Và</li>



<li>Sự hiểu biết chung về những gì tạo nên điều tốt nhất của chúng ta.</li>
</ul>



<p>Là một khái niệm trong tâm lý học tổ chức tích cực, AI có lẽ được hiểu rõ nhất bằng cách xem xét sự phát triển của nó theo thời gian.</p>



<h2 class="wp-block-heading">Tóm tắt lịch sử</h2>



<p>Sẽ rất hữu ích khi biết một chút về quản lý khoa học và &#8216;Chủ nghĩa Taylor&#8217; để xem làm thế nào và tại sao AI lại ra đời.</p>



<h3 class="wp-block-heading">Quản lý khoa học</h3>



<p>Hầu hết các nhà lãnh đạo và quản lý tổ chức đều đã biết về quản lý khoa học, nhưng đối với những người chưa biết thì đây là một trường phái tư tưởng nổi lên vào cuối thế kỷ 19.&nbsp;Mục tiêu của Quản lý khoa học là nâng cao hiệu quả của quy trình công việc bằng cách xem xét chúng một cách phân tích và loại bỏ lãng phí.</p>



<p>Vào thời điểm đó, <a href="https://www.britannica.com/biography/Frederick-W-Taylor" target="_blank" rel="noreferrer noopener">Frederick Taylor</a>, một kỹ sư người Mỹ, đã được truyền cảm hứng để áp dụng các kỹ thuật khoa học nghiêm ngặt để phân tích và cải thiện cách mọi người làm việc.&nbsp;Nhìn rộng ra, điều này là thông qua việc tính thời gian, đơn giản hóa và tiêu chuẩn hóa các nhiệm vụ.</p>



<p>Các phương pháp tiếp cận sau đó đã bị chỉ trích nặng nề vì thúc đẩy quan điểm coi doanh nghiệp như một cỗ máy chứ không phải là một thực thể của con người.&nbsp;Một điểm tương đồng thú vị khác là nó đặt trọng tâm khá rõ ràng vào&nbsp;các nguồn lực, hơn là phần&nbsp;con người&nbsp;trong nguồn nhân lực.&nbsp;Một trích dẫn trực tiếp từ chính người đàn ông đó đưa ra một ví dụ:</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>“Trong kế hoạch của chúng tôi, chúng tôi không yêu cầu sự chủ động của nhân viên. Chúng tôi không muốn có bất kỳ sáng kiến ​​nào.&nbsp;Tất cả những gì chúng tôi muốn ở họ là tuân theo những mệnh lệnh mà chúng tôi đưa ra, làm theo những gì chúng tôi nói và làm thật nhanh chóng.”</p>
<cite>(Taylor, 1919)</cite></blockquote>



<h3 class="wp-block-heading">Sửa chửa cỗ máy bị hỏng</h3>



<p>Quản lý khoa học ở dạng ban đầu đã không còn phổ biến trong gần 1 thế kỷ.&nbsp;Tuy nhiên, những người ủng hộ AI chỉ ra rất nhiều bằng chứng cho thấy tư duy &#8216;tập trung vào thâm hụt&#8217; vẫn được áp dụng nhiều trong thực tiễn quản lý và tổ chức (Cooperrider &amp; Srivastva, 1987).</p>



<p>Theo nghĩa này, việc thay đổi tổ chức là về việc xác định, thiết lập và sửa chữa những thứ không hoạt động—được Bushe (2013), một chuyên gia về AI, tóm tắt gọn gàng như “điều tra về những trải nghiệm còn thiếu sót”.</p>



<p>Các ví dụ thường được trích dẫn bao gồm phân tích nhu cầu của tổ chức, xác định vấn đề, phân tích nguyên nhân gốc rễ, v.v.</p>



<h3 class="wp-block-heading">Hướng tới cách tiếp cận dựa trên điểm mạnh</h3>



<p>Để phản ứng lại sự nhấn mạnh quá mức này, AI đã nổi lên như một cách tiếp cận thay thế cho sự thay đổi và phát triển của tổ chức;&nbsp;một cách tiếp cận khẳng định tập trung tìm hiểu xem điều gì đúng, điều gì đang hiệu quả và cách hướng tới tầm nhìn mong muốn (Davidcooperrider.com, 2019).</p>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="1280" height="720" src="https://media.huynhhieutravel.com/so-sanh-mo-hinh-giai-quyet-van-de-vs-mo-hinh-danh-gia-cao.jpg" alt="So sánh mô hình giải quyết vấn đề và mô hình đánh giá cao" class="wp-image-12125" srcset="https://media.huynhhieutravel.com/so-sanh-mo-hinh-giai-quyet-van-de-vs-mo-hinh-danh-gia-cao.jpg 1280w, https://media.huynhhieutravel.com/so-sanh-mo-hinh-giai-quyet-van-de-vs-mo-hinh-danh-gia-cao-768x432.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption class="wp-element-caption">So sánh mô hình giải quyết vấn đề và mô hình đánh giá cao</figcaption></figure>



<p>Như đã lưu ý, Mô hình điều tra đánh giá dựa trên nguyên tắc rằng tương lai tích cực của tổ chức có thể đạt được thông qua sự tham gia tập thể và các phương pháp “khẳng định, ép buộc và đẩy nhanh việc học tập trước” (Cooperrider và cộng sự, 2008).</p>



<p>Còn lâu mới mổ xẻ những sai lầm trong quá khứ và xác định con đường khắc phục phía trước.&nbsp;Xa hơn một chút, tôi sẽ xem xét kỹ hơn về mô hình và lý thuyết một cách chi tiết hơn.</p>



<h2 class="wp-block-heading">Một cái nhìn về David Cooperrider</h2>



<p>David Cooperrider thường được coi là người tiên phong trong Mô hình tìm hiểu đánh giá cao.&nbsp;Tuy nhiên, bản thân mô hình này đã được phát triển trong thập niên 80 bởi cả Cooperrider và Suresh Srivastva, người cố vấn của ông lúc bấy giờ.</p>



<h3 class="wp-block-heading">Sức mạnh của câu hỏi</h3>



<p>Cooperrider mô tả “Ah-Ha!”&nbsp;khoảnh khắc xảy ra khi anh ấy và một đồng nghiệp đang thực hiện nghiên cứu hành động cho một dự án phát triển tổ chức (Bushe, 2013).&nbsp;Cụ thể, nhóm nhận thấy mình đang ở trong bầu không khí ngày càng thù địch và tiêu cực và quyết định thay đổi cách tiếp cận.</p>



<p>Thay vì tìm hiểu xem điều gì không hiệu quả, Cooperrider và đồng nghiệp của ông quyết định hỏi xem điều gì đang hiệu quả &#8211; mặc dù ở một công ty khác (Barrett &amp; Cooperrider, 1990).</p>



<p>Sóng não ở đây là bản thân cuộc điều tra có thể định hình mạnh mẽ cách chúng ta nhìn nhận và phát triển hệ thống con người. Điều đó dẫn đến bằng tiến sĩ của Cooperrider&nbsp;về AI vào năm 1986.</p>



<h3 class="wp-block-heading">Từ nghiên cứu đến phỏng vấn đến phát triển tổ chức</h3>



<p>Những gì Cooperrider thực sự có vào thời điểm này là một cái nhìn sâu sắc có khả năng biến đổi về cách có thể cải thiện nghiên cứu khoa học xã hội định tính.</p>



<p>Nghĩa là, sự thay đổi mô hình cho sự thay đổi tổ chức đã không xảy ra ngay lập tức.&nbsp;<a href="http://www.gervasebushe.ca/Foundations_AI.pdf" target="_blank" rel="noreferrer noopener">Bushe (2013), người trình bày chi tiết</a>&nbsp;hơn về lịch sử của AI, mô tả cách tiếp cận tìm hiểu lần đầu tiên được dạy cho nhân viên để họ có thể lần lượt phỏng vấn các nhân viên khác bằng các phương pháp mới.</p>



<p>Nó đã được đón nhận một cách tích cực vì lợi ích của việc tạo ra ý tưởng nhanh chóng trở nên rõ ràng.</p>



<p>Sau đó, David Cooperrider bắt đầu làm việc với những người khác để khám phá cách áp dụng &#8216;chủ nghĩa xây dựng xã hội&#8217; này vào sự thay đổi tổ chức, cùng những thứ khác.&nbsp;Đến năm 1997, &#8216;mô hình 4D&#8217; mà ông đặt nền móng đã trở thành Mô hình tìm hiểu được đánh giá cao mà chúng ta biết ngày nay.</p>



<h2 class="wp-block-heading">Mô hình và lý thuyết</h2>



<p>Bất kỳ người thực hành phát triển tổ chức nào cũng sẽ biết rằng có rất nhiều khuôn khổ trong lĩnh vực này.&nbsp;Mô hình 4D thường đề cập đến sự trình bày trực quan về 4 bước của sáng kiến ​​AI:</p>



<ul class="wp-block-list">
<li>Discovery (Khám phá);</li>



<li>Dream (Mơ);</li>



<li>Design (Thiết kế);</li>



<li>và Định mệnh (Destiny).</li>
</ul>



<p>Tuy nhiên, bạn sẽ thường thấy bước thứ 5 được thêm vào, đối với Define (Xác định), bước này chỉ liên quan đến những gì David Cooperrider mô tả là chọn một chủ đề khẳng định.&nbsp;Ngược lại, một chủ đề khẳng định là trọng tâm của sự can thiệp của bạn &#8211; có thể có một hoặc có thể có nhiều tiêu điểm.</p>



<p>Ví dụ có thể bao gồm sự hài lòng của khách hàng cao hơn, môi trường làm việc an toàn hơn hoặc mang lại giá trị hiệu quả hơn (Kessler, 2013).</p>



<p>Dưới đây là một ví dụ về Mô hình AI không có phần Xác định.</p>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="1280" height="720" src="https://media.huynhhieutravel.com/mo-hinh-4d-yeu-cau-danh-gia-cao.jpg" alt="Mô hình 4D yêu cầu đánh giá cao" class="wp-image-12124" srcset="https://media.huynhhieutravel.com/mo-hinh-4d-yeu-cau-danh-gia-cao.jpg 1280w, https://media.huynhhieutravel.com/mo-hinh-4d-yeu-cau-danh-gia-cao-768x432.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption class="wp-element-caption">Mô hình 4D yêu cầu đánh giá cao</figcaption></figure>



<h3 class="wp-block-heading">Các bước trong mô hình 4D</h3>



<p>Bước Xác định là một phần quan trọng trong việc xác định các bước sau sẽ diễn ra như thế nào.&nbsp;Kessler (2013) nhấn mạnh tầm quan trọng của việc sử dụng ngôn ngữ truyền cảm hứng để định hình trọng tâm can thiệp của bạn.</p>



<p>Vì vậy, sự hài lòng của khách hàng lớn hơn có thể trở thành điều mà ông mô tả là “<em>truyền cảm hứng cho những khách hàng trung thành cuồng nhiệt</em>”.</p>



<p>Các chủ đề khẳng định hiện đã được thiết lập, đây là các giai đoạn (Ludema và cộng sự, 2006):</p>



<h4 class="wp-block-heading">1. Khám phá</h4>



<p>Trọng tâm trong giai đoạn này là tìm kiếm và xác định những gì mang lại sức sống cho tổ chức.&nbsp;Những thành công trong quá khứ có thể được thảo luận và khám phá, và trong mỗi trường hợp, mục tiêu là trau dồi những gì đã tạo nên chúng.</p>



<p>Đây hoàn toàn là hoạt động tìm hiểu tích cực và các bên liên quan trong nội bộ có thể đặt câu hỏi cho nhau để khám phá điều mà Ludema và các đồng nghiệp gọi là “điều tốt nhất của những gì hiện có”.</p>



<p>Mặc dù điều này tập trung vào việc phát hiện ra điểm mạnh nhưng cũng là một cách hữu ích để chuyển tư duy và vốn từ vựng hiện tại khỏi lối suy nghĩ tập trung vào thiếu sót.</p>



<h4 class="wp-block-heading">2. Giấc mơ</h4>



<p>Giai đoạn Giấc mơ là về việc tưởng tượng ra những tương lai tích cực tiềm tàng cho tổ chức.&nbsp;Bởi vì lý tưởng nhất là có nhiều người tham gia tham gia vào quá trình AI, nên những người này sẽ đại diện cho nhiều quan điểm, ý kiến ​​và hiểu biết khác nhau.</p>



<p>Những câu hỏi tích cực vô điều kiện đã được phát triển sẽ mở ra một cách lý tưởng những tầm nhìn và khả năng sáng tạo, mang tính xây dựng.&nbsp;Thông qua ngôn ngữ và hình ảnh tích cực, những người tham gia cùng nhau tạo ra tương lai và kết quả tích cực.</p>



<h4 class="wp-block-heading">3. Thiết kế</h4>



<p>Đồng sáng tạo tiếp tục trong giai đoạn này, nhưng trọng tâm chuyển sang tranh luận và thảo luận về các khả năng đã được tạo ra.</p>



<p>Mục tiêu là đạt được tầm nhìn hoặc giá trị chung mà nhóm hoặc những người tham gia thấy là có tiềm năng thực sự và tích cực.&nbsp;Do đó, những nguyện vọng cá nhân sẽ được chia sẻ, trong một môi trường lý tưởng là hòa nhập, an toàn và hỗ trợ, nơi mọi người đều cảm thấy được lắng nghe.</p>



<h4 class="wp-block-heading">4. Định mệnh</h4>



<p>Mục tiêu của giai đoạn cuối cùng này (trước đây gọi là Giao hàng) là xây dựng tương lai “thông qua đổi mới và hành động” (Ludema et al., 2006: 158).</p>



<p>Tầm nhìn, hệ thống hoặc cơ cấu đã được thiết kế cam kết sử dụng các phương tiện có thể để đạt được chúng sẽ được hoàn thiện hơn nữa thông qua cam kết của từng cá nhân.</p>



<p>Điều đáng nói là giai đoạn Định mệnh của mô hình 4D không được xác định chặt chẽ về cách tiến hành. Kessler lập luận rằng các cá nhân thực hành và lý thuyết sẽ có cách khuyến khích cấu trúc hoặc ứng biến khác nhau trong giai đoạn này (Kessler, 2013).</p>



<h3 class="wp-block-heading">Nguyên tắc cơ bản của việc điều tra đánh giá cao</h3>



<p>Khi AI ngày càng được ứng dụng rộng rãi hơn, chúng ta cũng đã thấy nhiều thực tiễn tương phản và xung đột được cho là thuộc phạm vi bảo trợ của AI.</p>



<p>Đây là điều mà Bushe (2013) cho là nguyên nhân ban đầu thiếu phương pháp luận chính thức—Giáo sư Cooperrider lúc đầu đã do dự khi xuất bản bất kỳ phương pháp nào.&nbsp;Nhưng vào đầu thập kỷ trước, ông và Tiến sĩ Diana Whitney từ Viện Taos đã phát triển 5 nguyên tắc thực hành AI.</p>



<h4 class="wp-block-heading">1. Nguyên tắc xây dựng</h4>



<p>Điều này thừa nhận rằng niềm tin chủ quan của chúng ta về điều gì là đúng sẽ quyết định hành động, suy nghĩ và hành vi của chúng ta.</p>



<p>Ngôn ngữ mà chúng tôi sử dụng hàng ngày có vai trò then chốt trong cách chúng tôi cùng xây dựng tổ chức của mình và điều này bao gồm cả ngôn ngữ chúng tôi sử dụng để tìm hiểu.</p>



<p>Bản thân việc tìm hiểu là việc tạo ra và truyền cảm hứng cho những ý tưởng, tầm nhìn và câu chuyện mới có khả năng dẫn đến hành động (Cooperrider &amp; Whitney, 1999).</p>



<h4 class="wp-block-heading">2. Nguyên tắc đồng thời</h4>



<p>Điều này cho thấy rằng những tìm hiểu của chúng ta về hệ thống của con người có thể khiến chúng thay đổi. Những câu hỏi đầu tiên chúng tôi hỏi có thể định hình cách mọi người suy nghĩ và thảo luận về mọi thứ;&nbsp;đến lượt nó, điều này ảnh hưởng đến cách họ học hỏi và khám phá mọi thứ.</p>



<p>Không có cái gọi là câu hỏi trung lập, theo nghĩa là những câu hỏi nhiệt tình và kiên trì theo những hướng cụ thể sẽ dẫn đến sự thay đổi theo những hướng đó (Cooperrider &amp; Whitney, 1999; Whitney &amp; Trosten-Bloom, 2003).</p>



<h4 class="wp-block-heading">3. Nguyên tắc thơ ca</h4>



<p>Nguyên tắc thứ ba cho rằng chúng ta có thể chọn – hoặc không – nghiên cứu đời sống tổ chức để tạo ra sự khác biệt.&nbsp;Cuộc sống trong các hệ thống của con người, chẳng hạn như các tổ chức và đội nhóm, được đồng tác giả và kể trong các câu chuyện.</p>



<p>Sự lựa chọn từ vựng của chúng ta có thể khơi dậy cảm xúc, hình ảnh, khái niệm và sự hiểu biết, còn AI thì sử dụng câu hỏi để tạo ra những tầm nhìn tích cực, lạc quan về tương lai nhằm truyền cảm hứng và đánh thức &#8216;những điều tốt đẹp nhất trong con người&#8217; (Cooperrider &amp; Whitney, 1999; Kessler, 2013 ).</p>



<h4 class="wp-block-heading">4. Nguyên tắc đoán trước</h4>



<p>Nguyên tắc dự đoán gợi ý rằng hành động và hành vi hiện tại của chúng ta được định hình bởi tầm nhìn của chúng ta về tương lai.</p>



<p>Thông qua AI, chúng ta có thể tạo ra những hình ảnh và tầm nhìn tích cực về tương lai của chúng ta hoặc của tổ chức, điều này sẽ tác động đến những gì chúng ta làm trong hiện tại (Goleman, 1987; Cooperrider &amp; Whitney, 1999).</p>



<h4 class="wp-block-heading">5. Nguyên tắc tích cực</h4>



<p>Điều này thừa nhận rằng để khuyến khích động lực, chúng ta phải đặt những câu hỏi tích cực nhằm nhấn mạnh cốt lõi tích cực của một tổ chức.&nbsp;Sự thay đổi lâu dài phụ thuộc vào sự kết nối xã hội và ảnh hưởng tích cực giữa mọi người.</p>



<p>Những cảm xúc tích cực như sự nhiệt tình, gắn kết, hy vọng và hạnh phúc khuyến khích những ý tưởng sáng tạo và cởi mở với những ý tưởng đổi mới (Barrett &amp; Fry, 2005; Stavros &amp; Torres, 2005).</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>5 nguyên tắc AI này được trích dẫn phổ biến nhất và hiện đã được thiết lập vững chắc.&nbsp;Tuy nhiên, khi phương pháp Điều tra đánh giá ngày càng trở nên phổ biến hơn, chúng ta đang thấy những nguyên tắc mới nổi đang được đề xuất.</p>



<p>Trong số này có các nguyên tắc như tính trọn vẹn, ban hành, nhận thức, tự do lựa chọn, tường thuật và tính đồng bộ (Whitney &amp; Trosten-Bloom, 2003; Stratton-Berkeessel &amp; Myers, 2019).</p>
</blockquote>



<h2 class="wp-block-heading">Ví dụ về phương pháp tiếp cận</h2>



<p>Trong phần này, chúng ta sẽ xem xét sâu hơn một ví dụ về AI được ứng dụng để thay đổi tổ chức và bạn cũng sẽ tìm thấy một số liên kết hữu ích khác tới nhiều nghiên cứu điển hình hơn về chủ đề này.</p>



<h3 class="wp-block-heading">Tổ chức Cứu trợ và Phát triển Toàn cầu</h3>



<p><a href="https://www.preventionweb.net/organization/global-relief-and-development-mission" target="_blank" rel="noreferrer noopener">Tổ chức Cứu trợ và Phát triển Toàn cầu (GRDO)</a>, được Ludema và các đồng nghiệp giới thiệu trong Sổ tay Nghiên cứu Hành động (2006), là một tổ chức phi chính phủ của Hoa Kỳ và Canada có liên quan đến hơn một trăm tổ chức khác trên toàn thế giới.</p>



<h4 class="wp-block-heading">Bối cảnh</h4>



<p>GRDO đã tiếp cận các tác giả về vấn đề mà họ cho là có vấn đề với hệ thống đánh giá năng lực tổ chức hiện tại đối với các đối tác của mình.</p>



<p>Khi mô tả tình hình cho các chuyên gia tư vấn, họ đề cập đến việc thiếu sự tham gia của các bên liên quan (nội bộ và bên ngoài) với hệ thống;&nbsp;mọi người không ủng hộ nó và họ coi đó là một sự áp đặt tẻ nhạt.</p>



<p>Đã ẩn chứa trong mô tả của họ về hệ thống, là từ vựng dựa trên sự thiếu hụt và những gợi ý đổ lỗi—cả giữa các tổ chức bên liên quan và bản thân GRDO.</p>



<p>Ngoài ra, các tác giả lưu ý rằng GRDO không thể tự coi mình là một đối tác bình đẳng trong những gì vốn được cho là một quá trình xây dựng năng lực và lại không được coi là như vậy.</p>



<h4 class="wp-block-heading">Chủ đề khẳng định</h4>



<p>Như vậy, bước đầu tiên là điều chỉnh lại vấn đề được nhận thức một cách tích cực và xác định một chủ đề khẳng định.&nbsp;Để đạt được mục tiêu (hoặc sự khởi đầu) này, các chuyên gia tư vấn đã đặt ra các câu hỏi nhằm khám phá &#8216;khao khát sâu sắc hơn&#8217; của GRDO.</p>



<p>Theo Johnson và các đồng nghiệp, những câu hỏi quan trọng đầu tiên là:</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p><em>“Bạn thực sự muốn gì từ quá trình này?&nbsp;Khi bạn khám phá những hy vọng táo bạo nhất và những khát vọng cao nhất của mình, cuối cùng bạn muốn gì?”</em></p>
</blockquote>



<p>Do đó, bước Xác định đã dẫn đến một số chủ đề;&nbsp;GRDO mong muốn nhiều điều tích cực (Ludema và cộng sự, 2006):</p>



<ul class="wp-block-list">
<li>Học hỏi lẫn nhau về cách xây dựng các tổ chức phi chính phủ năng động, lành mạnh;&nbsp;Và</li>



<li>Khám phá những cách mới để cộng tác bình đẳng với các đối tác của họ.</li>
</ul>



<h4 class="wp-block-heading">Khám phá</h4>



<p>Một nhóm toàn cầu đã được thành lập bao gồm các bên liên quan từ các khu vực khác nhau của GRDO trên khắp thế giới và các khóa tu theo nhóm lớn đã được tổ chức để cả GRDO và các bên liên quan có thể làm quen với AI.</p>



<p>Họ đã đưa ra các phiên bản hơi khác nhau của Giao thức phỏng vấn AI được hiển thị bên dưới.</p>



<p><strong>Giao thức phỏng vấn đánh giá cao</strong></p>



<ul class="wp-block-list">
<li>Hãy nghĩ về khoảng thời gian trong toàn bộ trải nghiệm của bạn với tổ chức khi bạn cảm thấy hào hứng nhất, gắn kết nhất và sống động nhất. Những động lực và yếu tố nào đã khiến nó trở thành một trải nghiệm tuyệt vời? Điều gì ở bạn, những người khác và tổ chức của bạn đã khiến trải nghiệm đó trở thành trải nghiệm tuyệt vời nhất đối với bạn?</li>



<li>Bạn coi trọng điều gì nhất ở bản thân, công việc và tổ chức của mình?</li>



<li>Thực tiễn tốt nhất của tổ chức của bạn là gì (cách bạn quản lý, cách tiếp cận, truyền thống)?</li>



<li>Những khía cạnh độc đáo nào trong văn hóa của bạn có ảnh hưởng tích cực nhất đến tinh thần, sức sống và hiệu quả của tổ chức cũng như công việc của tổ chức?</li>



<li>Yếu tố cốt lõi “mang lại sức sống” cho tổ chức của bạn là gì?</li>



<li>3 hy vọng quan trọng nhất mà bạn có để nâng cao sức khỏe và sức sống của tổ chức trong tương lai là gì?</li>
</ul>



<p><em>Nguồn: Ludema và cộng sự.&nbsp;(2006)</em></p>



<p>Với những câu hỏi tích cực vô điều kiện để định hướng cuộc điều tra, các tổ chức phi chính phủ đối tác khác nhau đã quay trở lại quốc gia nơi họ làm việc để thực hiện &#8216;các chuyến tham quan lắng nghe&#8217; (Ludema và cộng sự, 2006).</p>



<p>Những hoạt động này bao gồm hoạt động điều tra có sự tham gia của các thành viên cộng đồng mà các tổ chức phi chính phủ đang hợp tác, nhằm thu hút càng nhiều tiếng nói càng tốt trong khi khám phá những điểm mạnh cốt lõi tích cực của GRDO và các đối tác của nó.</p>



<p>Hàng nghìn người tham gia đã tham gia vào giai đoạn này, diễn ra trong suốt 1 năm.</p>



<h4 class="wp-block-heading">Mơ</h4>



<p>GRDO và các đối tác NGO của mình đã gặp lại nhau tại các buổi tĩnh tâm nhóm lớn để chia sẻ những điểm mạnh và câu chuyện từ những thắc mắc của họ.&nbsp;Điều này đã giúp họ nói lên tầm nhìn của mình về tương lai tích cực của tổ chức và bắt đầu nảy sinh ý tưởng cho cách tiếp cận chiến lược mới.</p>



<p>Ludema và các đồng nghiệp mô tả giai đoạn này là sự khởi đầu của quá trình thiết kế lại (Ludema et al., 2006: 162):</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>“Một sự bùng nổ ảo của những câu chuyện tích cực đang được chia sẻ và cách GRDO và các đối tác nói về bản thân họ, về nhau cũng như công việc chung của họ đang bắt đầu chuyển từ cuộc trò chuyện về thâm hụt sang cuộc trò chuyện về khả năng.”</p>
</blockquote>



<h4 class="wp-block-heading">Thiết kế</h4>



<p>Phối hợp với các đối tác của mình, GRDO bắt đầu khám phá một cách có hệ thống những cấu trúc xã hội nào có thể hiện thực hóa những tầm nhìn này.&nbsp;Điều này diễn ra trên quy mô toàn cầu, với hàng trăm cuộc họp được tiến hành.</p>



<p>Trong quá trình này, những người tham gia đã tạo ra các cấu trúc đáp ứng theo khu vực—”các đề xuất mang tính khiêu khích”—có thể liên kết các điểm mạnh được phát hiện với những tương lai lý tưởng có thể xảy ra hoặc những gì &#8216;có thể xảy ra&#8217;.</p>



<p>Thông qua sự hợp tác sâu hơn, những hệ thống này đã phát triển thành các hệ thống xây dựng năng lực mới đầy tiềm năng, khác biệt cơ bản với cách tiếp cận trước đây mà GRDO và các đối tác đã sử dụng.</p>



<p>Nhìn rộng ra, đây là những hoạt động mang tính tham gia nhiều hơn và được phân cấp trách nhiệm để các tổ chức phi chính phủ địa phương sẽ tạo ra các giải pháp phù hợp hơn ở các quốc gia khác nhau.</p>



<p>Các tác giả mô tả sự khởi đầu của một sự thay đổi hướng tới tư duy tập trung vào quan hệ đối tác hơn. Họ nhớ lại, sự bình đẳng mong muốn bắt đầu bộc lộ khi từ vựng thay đổi để trở nên giống từ vựng của các đối tác hơn.</p>



<h4 class="wp-block-heading">Định mệnh</h4>



<p>Năm thứ 3 và cũng là năm cuối cùng của hành trình GRDO và các tổ chức phi chính phủ chứng kiến ​​các sáng kiến ​​được chia sẻ và năng lượng ngày càng tăng xung quanh chúng.</p>



<p>Các hoạt động chung đã được triển khai ở các khu vực khác nhau sau đợt tĩnh tâm cuối cùng, chẳng hạn như khởi động các dự án gây quỹ mới ở địa phương và thiết kế lại tổ chức theo một cơ cấu mới, ít phân cấp hơn.</p>



<p>Chi tiết hơn về sáng kiến ​​AI toàn cầu này có thể được tìm thấy trong cuốn sách của Johnson và Ludema (1997), <em>Hợp tác để xây dựng và đo lường năng lực tổ chức: Bài học từ các tổ chức phi chính phủ trên khắp thế giới</em>&nbsp;.</p>



<h3 class="wp-block-heading">Ví dụ về câu hỏi được đánh giá cao hơn</h3>



<p>Nếu bạn đang tìm thêm ví dụ về AI trong thực tế, hãy thử những điều sau:</p>



<ul class="wp-block-list">
<li><a href="https://positivepsychology.com/appreciative-inquiry-tools/">4 Công cụ, bài tập và hoạt động điều tra đáng giá</a></li>



<li><a href="https://positivepsychology.com/appreciative-inquiry-process/">Cách áp dụng quy trình tìm hiểu đánh giá cao (Bao gồm 5 mẹo)</a></li>



<li><a href="https://positivepsychology.com/appreciative-inquiry-questions/">Hơn 119 câu hỏi và ví dụ phỏng vấn yêu cầu đánh giá cao</a></li>



<li>Nhiều bài viết và&nbsp;<a href="http://www.davidcooperrider.com/case-studies/" target="_blank" rel="noreferrer noopener">nghiên cứu điển hình khác</a>&nbsp;từ các nhóm và tổ chức được cung cấp bởi Davidcooperrider.com.</li>
</ul>



<h2 class="wp-block-heading">Những lời chỉ trích về phương pháp: Ưu và nhược điểm của Khung</h2>



<p>Vì vậy, những ưu điểm và nhược điểm của Mô hình tìm hiểu đánh giá nói chung là gì?&nbsp;May mắn thay, những người khác trước chúng tôi đã xem xét tài liệu nên chúng tôi có thể tự rút ra kết luận (Drew &amp; Wallis, 2014).&nbsp;Trước tiên hãy nhìn vào chuyên gia.</p>



<h3 class="wp-block-heading">Ưu điểm tiềm năng của AI</h3>



<ul class="wp-block-list">
<li>Đầu tiên, AI tập trung vào các điểm mạnh, được cho là cung cấp năng lượng cho các tổ chức để thay đổi và đổi mới tích cực (Ludema và cộng sự, 2006; Bright, 2009);</li>



<li>Việc tận dụng điểm mạnh cũng cho phép nhân viên nâng cao trình độ của mình (Linley và cộng sự, 2010);</li>



<li>Nó khuyến khích văn hóa học tập thông qua tìm hiểu tập thể và trang bị cho mọi người những kỹ năng để tự khám phá (Conklin &amp; Hartman, 2014);</li>



<li>Vì vậy, nó khuyến khích tư duy sáng tạo, ý tưởng và có khả năng thúc đẩy các phương pháp tiếp cận đổi mới (Cooperrider &amp; Srivastva, 1987; Cooperrider và cộng sự, 2008);</li>



<li>Ngược lại, những điều này tạo điều kiện thuận lợi cho khả năng thích ứng của tổ chức – một lợi thế cạnh tranh quan trọng trong môi trường kinh doanh năng động (Basadur, 2004);</li>



<li>Văn hóa học tập cũng khuyến khích sự thay đổi bền vững (Boyce, 2003);</li>



<li>Về mặt thiết kế, nó nhằm mục đích khuyến khích sự tham gia của các bên liên quan (Drew &amp; Wallis, 2014);</li>



<li>Thông qua sự tham gia, nó tìm cách thúc đẩy sự cam kết hơn là phản kháng (Lines, 2004; Drew &amp; Wallis, 2014);&nbsp;Và</li>



<li>Khung 4D, thông qua cấu trúc của nó, cho phép mọi người hiểu rõ hơn về hành động (Bright, 2009).</li>
</ul>



<p>Có một chủ đề nhất quán trong phần lớn những lợi thế tiềm năng này;&nbsp;đây là câu hỏi Đánh giá cao đề cập đến sự thay đổi ở cấp độ văn hóa, thay vì trình bày cách tiếp cận phân tích để &#8216;khắc phục&#8217; các vấn đề cụ thể.</p>



<p>Thật vậy, AI khuyến khích cách tiếp cận hệ thống toàn diện, tiền đề cơ bản của nó không phải là &#8216;từ trên xuống&#8217; hay &#8216;từ dưới lên&#8217; (Davidcooperrider.com, 2019).</p>



<p>Theo hướng đó, chúng ta hãy xem xét những nhược điểm tiềm ẩn của phương pháp Điều tra đánh giá cao.</p>



<h3 class="wp-block-heading">Nhược điểm tiềm ẩn của AI</h3>



<ul class="wp-block-list">
<li>AI cần có thời gian đáng kể—nó không phải là cách khắc phục nhanh chóng bằng sức tưởng tượng (Drew &amp; Wallis, 2014);</li>



<li>Thay đổi tổ chức quy mô lớn thông qua AI có thể tiêu tốn nhiều tài nguyên, đặc biệt nếu những người tham gia bị phân tán về mặt địa lý, như trường hợp nghiên cứu ở trên;</li>



<li>Nó phụ thuộc rất nhiều vào mức độ có thể tạo ra một môi trường chia sẻ tích cực, hỗ trợ và cởi mở (Cooperrider &amp; Whitney, 1999; Ludema và cộng sự, 2003);</li>



<li>Không phải tất cả các bên liên quan luôn có thể tham gia một cách thực tế (Schooley, 2012);&nbsp;Và</li>



<li>Nếu tất cả các bên liên quan không thể tham gia, điều này sẽ đặt ra câu hỏi xung quanh đạo đức đạo đức của việc lập chiến lược với những gì về cơ bản không phải là sự đồng thuận dân chủ (Schooley, 2012).</li>
</ul>



<p>Do đó, để tổng hợp những điểm yếu, Drew và Wallis (2014) cho rằng việc lập kế hoạch cẩn thận trở nên quan trọng khi chúng ta xem xét sử dụng AI trong các bối cảnh cụ thể.&nbsp;Schooley (2012) sẽ nhấn mạnh rằng các ứng dụng AI của chính phủ và khu vực công có thể đặc biệt có vấn đề.</p>



<h2 class="wp-block-heading">SOAR là gì?</h2>



<p>Tóm lại, SOAR là một khuôn khổ chiến lược dựa trên các nguyên tắc AI.&nbsp;Sự song song đơn giản nhất với một mô hình được biết đến rộng rãi hơn sẽ là SWOT.</p>



<p>Cả hai đều liên kết các yếu tố nội bộ của công ty với các yếu tố bên ngoài và tương lai tiềm năng để cho phép áp dụng cách tiếp cận mang tính phân tích đối với chiến lược.</p>



<h3 class="wp-block-heading">Khung SOAR</h3>



<p>SOAR là viết tắt của (Stavros và cộng sự, 2003):</p>



<ul class="wp-block-list">
<li>Strengths (Điểm mạnh) – Tương tự như điểm mạnh SWOT, những điểm mạnh này liên quan đến các yếu tố bên trong hiện có.&nbsp;Chúng có thể là nguồn lực nội bộ, động lực hoặc thậm chí các khía cạnh của cơ cấu tổ chức có thể được tận dụng một cách chiến lược để đạt được lợi thế cạnh tranh;</li>



<li>Opportunities (Cơ hội) – Đây là những yếu tố bên ngoài tồn tại trong môi trường kinh tế vĩ mô, ngành hoặc thị trường của công ty;</li>



<li>Aspirations (Khát vọng) – Khát vọng là những tương lai tiềm năng tích cực cho công ty, bao gồm cả cách công ty có thể tạo ra giá trị.&nbsp;Lý tưởng nhất là những điều này có thể liên quan chặt chẽ đến tầm nhìn chiến lược của công ty và lý tưởng nhất là cam kết tập thể có thể được khuyến khích xung quanh tầm nhìn này;&nbsp;Và</li>



<li>Results (Kết quả) – Đây có thể được coi là sản phẩm có thể bàn giao và cho phép thực hiện cũng như đánh giá tiến trình của công ty khi công ty hướng tới mục tiêu của mình.</li>
</ul>



<p>Dưới đây là phiên bản điều chỉnh của ứng dụng ví dụ SOAR của Stavros và cộng sự (2003).&nbsp;Tại đây, có thể thấy&nbsp;<em>các Yếu tố bên trong</em>&nbsp;và&nbsp;<em>Yếu tố bên ngoài</em>&nbsp;(từ SWOT) được thay thế như các danh mục hoạch định chiến lược bằng&nbsp;<em>Điều tra chiến lược</em>&nbsp;và&nbsp;<em>Ý định đánh giá cao</em>&nbsp;trong SOAR.</p>



<figure class="wp-block-table"><table><tbody><tr><td><em></em><em>Điều&nbsp;</em><em>tra chiến lược</em><br><em></em></td><td>Điểm mạnh<br>Tài sản lớn nhất của chúng ta là gì?</td><td>Cơ hội<br>Cơ hội thị trường tốt nhất có thể là gì?</td></tr><tr><td><em>Ý định đánh giá cao</em></td><td>Khát vọng<br>Tương lai ưa thích của chúng ta là gì?</td><td>Kết quả Kết<br>quả có thể đo lường được là gì?</td></tr></tbody></table></figure>



<p>Nguồn: Chuyển thể từ Stavros et al.&nbsp;(2003: 11; 12)</p>



<h3 class="wp-block-heading">SOAR so với SWOT</h3>



<p>Như chúng ta mong đợi từ khung AI, mô hình SOAR bắt đầu bằng việc tìm hiểu.&nbsp;Đây là giai đoạn đầu tiên trong bốn giai đoạn mà người tham gia có thể trải qua với tư cách là một nhóm (Stavros và cộng sự, 2003):</p>



<p><strong>1. Tìm hiểu</strong>: Các câu hỏi tích cực được đặt ra để khám phá những điểm mạnh và nguyện vọng của tổ chức, đồng thời đây là cơ hội tốt để thảo luận cởi mở, tích cực về những hiểu biết chung (hoặc không) về các giá trị và tầm nhìn (Stavros và cộng sự, 2003).</p>



<p>Chúng ta muốn ở đâu?&nbsp;Những điểm mạnh nào đã giúp chúng ta đạt được vị trí hiện tại?&nbsp;Như thế nào và tại sao?</p>



<p><strong>2. Trí tưởng tượng</strong>: Người tham gia nghĩ ra những tương lai tiềm năng.&nbsp;Tầm nhìn, giá trị và sứ mệnh được đồng sáng tạo và việc lặp lại có thể là một phương tiện hữu ích để làm rõ hoặc tái khẳng định định hướng chiến lược của công ty.</p>



<p>Trọng tâm của giai đoạn tưởng tượng là các mục tiêu dài hạn cho một tương lai tốt đẹp hơn là chủ động quản lý rủi ro với các mối đe dọa hoặc điểm yếu trong tâm trí.</p>



<p><strong>3. Đổi mới</strong>: Các mục tiêu chiến lược dài hạn được chia thành các mục tiêu ngắn hạn và phương pháp để đạt được chúng.&nbsp;Đối với một dự án cụ thể, điều này có thể liên quan đến việc phát triển các sản phẩm và khung thời gian;&nbsp;theo nghĩa tổng quát hơn, đó là việc đưa ra các hệ thống để hỗ trợ việc thực hiện.</p>



<p><strong>4. Truyền cảm hứng</strong>: Stavros và các đồng nghiệp giới thiệu&nbsp;Inspire&nbsp;như một giải pháp thay thế cho những gì được coi là hệ thống kiểm soát theo truyền thống (tức là trong trang web văn hóa hoặc trong Quản lý chất lượng toàn diện).</p>



<p>Trong chiến lược thông thường, những điều này có thể đề cập đến KPI và các biện pháp khuyến khích;&nbsp;trong SOAR, truyền cảm hứng bao gồm các hệ thống khuyến khích sự công nhận và khen thưởng đích thực.</p>



<h3 class="wp-block-heading">Áp dụng SOAR</h3>



<p>Tất nhiên, hiểu một framework không giống như đưa nó vào hoạt động.&nbsp;Để đạt được mục tiêu đó, Stavros và Hinrichs (2009) phác thảo một số bước để áp dụng khung SOAR trong&nbsp;<em>Cuốn sách mỏng về bay cao</em>&nbsp;của họ.&nbsp;9 bước của họ như sau:</p>



<ol class="wp-block-list">
<li>Xác định các bên liên quan – Xác định ai sẽ tham gia vào hoạt động này và quyết định cách thức họp.&nbsp;Để phù hợp với mục tiêu hợp tác, toàn diện của AI, những người tham gia phải là các bên liên quan nội bộ đại diện cho các lĩnh vực khác nhau của công ty.</li>



<li>Thiết kế cuộc phỏng vấn AI của bạn – Lên kế hoạch cho các câu hỏi mà bạn định sử dụng;&nbsp;tất nhiên, những điều này sẽ nhằm mục đích phát triển cái nhìn sâu sắc hơn về cốt lõi tích cực của tổ chức.&nbsp;Hiểu được điểm mạnh, thành công và khát vọng của nó là động lực chính, vì vậy câu hỏi của bạn phải phản ánh những mục tiêu này.</li>



<li>Thu hút các bên liên quan – Những hoạt động này sẽ luôn có sự tham gia của các bên liên quan nội bộ và cũng có thể bao gồm các bên liên quan bên ngoài như đối tác, khách hàng hoặc nhà cung cấp nếu thấy phù hợp.&nbsp;Sử dụng câu hỏi của bạn để khám phá những khả năng và tương lai tiềm năng tích cực.</li>



<li>Điều chỉnh lại vấn đề – Các vấn đề sẽ luôn nảy sinh để thảo luận;&nbsp;Cuộc điều tra SOAR tập trung vào sự tập trung tích cực, vì vậy hãy định hình lại các cuộc trò chuyện để xem xét các kết quả mong muốn thay vì tránh né hoặc giảm thiểu các mối đe dọa.</li>



<li>Tóm tắt – Đây là việc làm rõ và khẳng định điểm mạnh của tổ chức – cốt lõi tích cực của tổ chức.</li>



<li>Thiết lập nguyện vọng và xác định kết quả – Đây là một phần quan trọng trong việc xác định hoặc xác định lại tầm nhìn tương lai của tổ chức, điều này lý tưởng sẽ tận dụng những điểm mạnh mà bạn đã xác định chung.&nbsp;Những thứ này sẽ trông như thế nào?&nbsp;Họ sẽ như thế nào?</li>



<li>Đánh giá cơ hội – Nhìn vào những cơ hội đã được tạo ra.&nbsp;Đó là những gì mong muốn nhất?&nbsp;Cái nào mới, sáng tạo và đầy tiềm năng?</li>



<li>Mục tiêu thủ công – Mục tiêu phải xuất phát từ các cơ hội được xác định ở giai đoạn trước.&nbsp;Chúng có thể được liên kết với kết quả để có thể theo dõi và đánh giá tiến độ.&nbsp;Sử dụng các tuyên bố mục tiêu để rõ ràng hơn.</li>



<li>Tạo kế hoạch hành động – Chúng ta sẽ làm việc như thế nào để hướng tới những mục tiêu này?&nbsp;Các kế hoạch hành động cần tạo điều kiện thuận lợi cho việc thực hiện và có thể có kế hoạch cụ thể cho từng mục tiêu.</li>
</ol>



<p>Được triển khai đúng cách với sự tham gia của một nhóm các bên liên quan, khuôn khổ SOAR có mục đích lý tưởng là khuyến khích cam kết tập thể đối với tầm nhìn chung đã xuất hiện (Stavros &amp; Hinrichs, 2009).</p>



<h2 class="wp-block-heading">Hội nghị thượng đỉnh điều tra đánh giá cao</h2>



<p>Bạn sẽ nhận thấy từ ví dụ Câu hỏi đánh giá cao ở trên rằng các cuộc họp quy mô lớn (hoặc các cuộc họp tĩnh tâm hoặc tương tự) được đề cập khá thường xuyên.</p>



<p>&#8216;Các cuộc rút lui quy mô lớn&#8217; được mô tả là Hội nghị thượng đỉnh tìm hiểu đánh giá cao (Hội nghị thượng đỉnh AI), thường kéo dài vài ngày và quy tụ tất cả những người tham gia có liên quan cho sáng kiến ​​4D.</p>



<p>Nói cách khác:</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>“một cuộc họp lập kế hoạch, thiết kế hoặc triển khai của một nhóm lớn nhằm tập hợp toàn bộ hệ thống các bên liên quan bên trong và bên ngoài lại với nhau một cách tập trung để thực hiện một nhiệm vụ có giá trị chiến lược và đặc biệt là sáng tạo.”</p>
</blockquote>



<p>(Cooperrider, 2019)</p>



<p>Cuốn sách cùng tên của Ludema và Mohr (2003) trình bày chi tiết hơn về phương pháp này;&nbsp;năm phần lần lượt nhìn vào:</p>



<ol class="wp-block-list">
<li>Hiểu phương pháp luận, các điều kiện thiết yếu và những gì mong đợi từ đầu đến cuối;</li>



<li>Tài trợ, lập kế hoạch và tổ chức Hội nghị thượng đỉnh AI;</li>



<li>4-D trong Hội nghị thượng đỉnh và thông tin dành cho người điều phối;</li>



<li>Theo dõi và xem xét các tổ chức được đánh giá cao;&nbsp;Và</li>



<li>Một phụ lục có ghi chú và một sổ làm việc mẫu.</li>
</ol>



<p>Bạn có thể tải&nbsp;<em>Hội nghị thượng đỉnh về yêu cầu đánh giá cao: Hướng dẫn dành cho người thực hành</em>&nbsp;tại&nbsp;<a href="https://www.amazon.com/Appreciative-Inquiry-Summit-Practitioners-Large-Group/dp/1576752488" target="_blank" rel="noreferrer noopener">Amazon</a>.</p>
', 'Tìm hiểu về mô hình Điều tra đánh giá cao (Appreciative Inquiry &#8211; AI), một cách tiếp cận hợp tác, dựa trên thế mạnh để thay đổi trong các tổ chức.', NULL, 'post', '2024-09-04 21:16:10', '2024-09-06 21:04:38');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (12126, 434);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (12112, 'Phong Cách Học Tập Và Chu Trình Học Tập Trải Nghiệm Của Kolb', 'phong-cach-va-chu-trinh-hoc-tap-trai-nghiem-cua-kolb', '
<p><a href="https://en.wikipedia.org/wiki/David_A._Kolb" target="_blank" rel="noreferrer noopener">David Kolb</a>&nbsp;đã xuất bản mô hình phong cách học tập của mình vào năm 1984, từ đó ông đã phát triển bản liệt kê phong cách học tập của mình.</p>



<p>Lý thuyết học tập trải nghiệm của Kolb hoạt động trên 2 cấp độ: chu trình học tập gồm 4 giai đoạn và 4 phong cách học tập riêng biệt.&nbsp;Phần lớn lý thuyết của Kolb liên quan đến quá trình nhận thức bên trong của người học.</p>



<p>Kolb cho rằng việc học liên quan đến việc tiếp thu các khái niệm trừu tượng có thể áp dụng linh hoạt trong nhiều tình huống.&nbsp;Theo lý thuyết của Kolb, động lực phát triển các khái niệm mới được cung cấp bởi những trải nghiệm mới.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>“Học tập là quá trình trong đó kiến thức được tạo ra thông qua việc chuyển đổi kinh nghiệm” (Kolb, 1984, trang 38).</p>
</blockquote>



<h2 class="wp-block-heading">Chu Trình Học Tập Trải Nghiệm</h2>



<p>Lý thuyết về phong cách học tập theo trải nghiệm của Kolb thường được thể hiện bằng một chu trình học tập gồm 4 giai đoạn, trong đó người học “chạm vào tất cả các cơ sở”:</p>



<figure class="wp-block-image size-full" id="attachment_553"><img loading="lazy" decoding="async" width="942" height="942" src="https://media.huynhhieutravel.com/chu-trinh-hoc-tap-trai-nghiem.jpg" alt="Chu trình học tập trải nghiệm Kolb" class="wp-image-12122" srcset="https://media.huynhhieutravel.com/chu-trinh-hoc-tap-trai-nghiem.jpg 942w, https://media.huynhhieutravel.com/chu-trinh-hoc-tap-trai-nghiem-300x300.jpg 300w, https://media.huynhhieutravel.com/chu-trinh-hoc-tap-trai-nghiem-150x150.jpg 150w, https://media.huynhhieutravel.com/chu-trinh-hoc-tap-trai-nghiem-768x768.jpg 768w" sizes="(max-width: 942px) 100vw, 942px" /><figcaption class="wp-element-caption">Chu trình học tập trải nghiệm Kolb</figcaption></figure>



<ol class="wp-block-list">
<li><strong>Trải nghiệm cụ thể</strong> – người học gặp phải một trải nghiệm cụ thể. Đây có thể là một trải nghiệm hoặc tình huống mới hoặc sự diễn giải lại trải nghiệm hiện có dưới ánh sáng của các khái niệm mới.</li>



<li><strong>Quan sát phản ánh trải nghiệm mới</strong> – người học phản ánh về trải nghiệm mới dưới ánh sáng kiến thức hiện có của họ. Điều đặc biệt quan trọng là bất kỳ sự mâu thuẫn nào giữa kinh nghiệm và sự hiểu biết.</li>



<li><strong>Khái niệm hóa trừu tượng</strong> – sự phản ánh làm nảy sinh một ý tưởng mới hoặc sửa đổi một khái niệm trừu tượng hiện có (người đó đã học được từ kinh nghiệm của họ).</li>



<li><strong>Thử nghiệm tích cực</strong> – các khái niệm mới được tạo hoặc sửa đổi sẽ dẫn đến thử nghiệm. Người học áp dụng (các) ý tưởng của mình vào thế giới xung quanh để xem điều gì sẽ xảy ra.</li>
</ol>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>Học tập hiệu quả được thấy khi một người tiến bộ qua 1 chu kỳ gồm 4 giai đoạn:</p>



<p>(1) có một trải nghiệm cụ thể, sau đó là (2) quan sát và suy ngẫm về trải nghiệm đó dẫn đến (3) hình thành các khái niệm trừu tượng (phân tích) và khái quát hóa (kết luận) mà sau đó (4) được sử dụng để kiểm tra một giả thuyết trong các tình huống trong tương lai, dẫn đến những trải nghiệm mới.</p>
</blockquote>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="812" height="812" src="https://media.huynhhieutravel.com/chu-trinh-hoc-tap-Kolbs.jpg" alt="" class="wp-image-12121" srcset="https://media.huynhhieutravel.com/chu-trinh-hoc-tap-Kolbs.jpg 812w, https://media.huynhhieutravel.com/chu-trinh-hoc-tap-Kolbs-300x300.jpg 300w, https://media.huynhhieutravel.com/chu-trinh-hoc-tap-Kolbs-150x150.jpg 150w, https://media.huynhhieutravel.com/chu-trinh-hoc-tap-Kolbs-768x768.jpg 768w" sizes="(max-width: 812px) 100vw, 812px" /></figure>



<p>Kolb xem việc học tập như một quá trình tích hợp, trong đó mỗi giai đoạn hỗ trợ lẫn nhau và bổ sung cho giai đoạn tiếp theo. Có thể tham gia vào chu trình ở bất kỳ giai đoạn nào và thực hiện theo trình tự logic của nó.</p>



<p>Tuy nhiên, việc học hiệu quả chỉ xảy ra khi người học có thể thực hiện được cả 4 giai đoạn của mô hình. Do đó, không có giai đoạn nào của chu trình tự nó có hiệu quả như một quá trình học tập.</p>



<p>Quá trình trải qua chu trình dẫn đến việc hình thành các ‘mô hình tinh thần’ ngày càng phức tạp và trừu tượng về bất cứ điều gì người học đang học.</p>



<h2 class="wp-block-heading">Chu Kỳ Suy Ngẫm Của Kolb</h2>



<p>Lý thuyết học tập của Kolb đặt ra 4 phong cách học tập riêng biệt, dựa trên chu trình học tập 4 giai đoạn (xem ở trên).&nbsp;Kolb giải thích rằng những người khác nhau sẽ thích một phong cách học tập khác nhau một cách tự nhiên.</p>



<p>Có nhiều yếu tố khác nhau ảnh hưởng đến phong cách ưa thích của một người.&nbsp;Ví dụ: môi trường xã hội, trải nghiệm giáo dục hoặc cấu trúc nhận thức cơ bản của cá nhân.</p>



<p>Bất kể điều gì ảnh hưởng đến việc lựa chọn phong cách, bản thân sở thích về phong cách học tập thực sự là sản phẩm của 2 cặp biến số hoặc 2 “lựa chọn” riêng biệt mà chúng ta đưa ra, mà Kolb trình bày dưới dạng các đường của một trục, mỗi lựa chọn có các phương thức “xung đột” ở hai đầu.</p>



<p>Một cách trình bày điển hình về 2 phạm vi liên tục của Kolb là trục đông-tây được gọi là Liên tục xử lý (cách chúng ta tiếp cận một nhiệm vụ) và trục bắc-nam được gọi là Liên tục nhận thức (phản ứng cảm xúc của chúng ta hoặc cách chúng ta suy nghĩ hoặc cảm nhận về Nó).</p>



<p>Kolb tin rằng chúng ta không thể thực hiện cả 2 biến số trên một trục cùng một lúc (ví dụ: suy nghĩ và cảm nhận).&nbsp;Phong cách học tập của chúng ta là sản phẩm của 2 quyết định lựa chọn này.</p>



<p>Thường dễ dàng hơn để thấy việc xây dựng các phong cách học tập của Kolb dưới dạng ma trận 2×2. Mỗi phong cách học tập đại diện cho sự kết hợp của hai phong cách ưa thích.</p>



<figure class="wp-block-image size-full" id="attachment_554"><img loading="lazy" decoding="async" width="1280" height="820" src="https://media.huynhhieutravel.com/truc-suy-ngam-cua-kolb.jpg" alt="Trục suy ngẫm của Kolb" class="wp-image-12120" srcset="https://media.huynhhieutravel.com/truc-suy-ngam-cua-kolb.jpg 1280w, https://media.huynhhieutravel.com/truc-suy-ngam-cua-kolb-768x492.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption class="wp-element-caption">Trục suy ngẫm của Kolb</figcaption></figure>



<p>Ma trận cũng nêu bật thuật ngữ của Kolb về 4 phong cách học tập;&nbsp;phân kỳ, đồng hóa và hội tụ, thích nghi:</p>



<figure class="wp-block-table"><table class="has-fixed-layout"><thead><tr><th>–</th><th>Thử nghiệm tích cực (Thực hiện)</th><th>Quan sát phản xạ (Xem)</th></tr></thead><tbody><tr><th>Trải nghiệm cụ thể (Cảm giác)</th><td>Thích nghi</td><td>Phân kỳ</td></tr><tr><th>Khái niệm trừu tượng (Suy nghĩ)</th><td>Hội tụ</td><td>Đồng hóa</td></tr></tbody></table></figure>



<h2 class="wp-block-heading">Mô Tả Phong Cách Học Tập</h2>



<p>Biết được phong cách học tập của một người (và của chính bạn) sẽ giúp việc học tập được định hướng theo phương pháp ưa thích.</p>



<p>Điều đó có nghĩa là mọi người đều phản ứng và cần sự kích thích của tất cả các loại phong cách học tập ở mức độ này hay mức độ khác – vấn đề là sử dụng sự nhấn mạnh phù hợp nhất với tình huống nhất định và sở thích về phong cách học tập của một người.</p>



<p>Dưới đây là những mô tả ngắn gọn về 4 phong cách học tập Kolb:</p>



<h3 class="wp-block-heading">Phân kỳ&nbsp;(cảm nhận và quan sát)</h3>



<p>Những người này có thể nhìn mọi thứ từ những quan điểm khác nhau. Họ rất nhạy cảm. Họ thích xem hơn là làm, có xu hướng thu thập thông tin và sử dụng trí tưởng tượng để giải quyết vấn đề. Họ giỏi nhất trong việc xem xét các tình huống cụ thể từ nhiều quan điểm khác nhau.</p>



<p>Kolb gọi phong cách này là “phân kỳ” vì những người này thể hiện tốt hơn trong những tình huống đòi hỏi phải tạo ra ý tưởng, chẳng hạn như động não.&nbsp;Những người có phong cách học tập khác nhau có mối quan tâm về văn hóa rộng rãi và thích thu thập thông tin.</p>



<p>Họ quan tâm đến mọi người, có xu hướng giàu trí tưởng tượng và giàu cảm xúc và có thiên hướng về nghệ thuật.&nbsp;Những người có phong cách khác biệt thích làm việc theo nhóm, lắng nghe với tinh thần cởi mở và nhận phản hồi cá nhân.</p>



<p>Một số kỹ thuật giảng dạy người Phân kỳ yêu thích:</p>



<ul class="wp-block-list">
<li>Các hoạt động thực hành và cơ hội khám phá</li>



<li>Bài giảng cổ điển dành cho giáo viên nêu bật cách sử dụng hệ thống cũng như điểm mạnh và điểm yếu của hệ thống đó.</li>
</ul>



<h3 class="wp-block-heading">Đồng hóa (quan sát và suy nghĩ)</h3>



<p>Sở thích học tập đồng hóa bao gồm một cách tiếp cận ngắn gọn, hợp lý.&nbsp;Ý tưởng và khái niệm quan trọng hơn con người.</p>



<p>Những người này yêu cầu những lời giải thích rõ ràng hơn là một cơ hội thực tế.&nbsp;Họ xuất sắc trong việc hiểu thông tin trên phạm vi rộng và sắp xếp nó theo một định dạng rõ ràng, hợp lý.</p>



<p>Những người có phong cách học tập hòa nhập ít tập trung vào con người mà quan tâm nhiều hơn đến các ý tưởng và khái niệm trừu tượng.&nbsp;Những người có phong cách này bị thu hút bởi những lý thuyết hợp lý hơn là những cách tiếp cận dựa trên giá trị thực tế.</p>



<p>Phong cách học tập này rất quan trọng để mang lại hiệu quả trong sự nghiệp thông tin và khoa học.&nbsp;Trong các tình huống học tập chính thức, những người có phong cách này thích đọc sách, nghe giảng, khám phá các mô hình phân tích và có thời gian để suy nghĩ thấu đáo.</p>



<p>Có một số kỹ thuật giảng dạy mà Người đồng hóa ưa thích:</p>



<ul class="wp-block-list">
<li>Các bài tập độc lập, được chuẩn bị sẵn mà người học có thể hoàn thành mà không cần người hướng dẫn</li>



<li>Bài giảng cổ điển của giáo viên được hỗ trợ bởi bản trình bày âm thanh hoặc video</li>



<li>Khám phá hoặc trình diễn riêng tư theo hướng dẫn, kèm theo câu trả lời được cung cấp.</li>
</ul>



<h3 class="wp-block-heading">Hội tụ&nbsp;(làm và suy nghĩ)</h3>



<p>Những người có phong cách học tập hội tụ có thể giải quyết vấn đề và sẽ sử dụng việc học của mình để tìm giải pháp cho các vấn đề thực tế.&nbsp;Họ thích các nhiệm vụ kỹ thuật hơn và ít quan tâm đến con người cũng như các khía cạnh giữa các cá nhân.</p>



<p>Những người có phong cách học tập hội tụ là những người giỏi nhất trong việc tìm ra những ứng dụng thực tế cho các ý tưởng và lý thuyết.&nbsp;Họ có thể giải quyết vấn đề và đưa ra quyết định bằng cách tìm giải pháp cho các câu hỏi và vấn đề.</p>



<p>Những người có phong cách học tập hội tụ bị thu hút bởi các nhiệm vụ và vấn đề kỹ thuật hơn là các vấn đề xã hội hoặc cá nhân.&nbsp;Một phong cách học tập hội tụ cho phép khả năng chuyên môn và công nghệ.</p>



<p>Những người có phong cách hội tụ thích thử nghiệm những ý tưởng mới, mô phỏng và làm việc với những ứng dụng thực tế.</p>



<p>Có một số kỹ thuật giảng dạy mà Người hội tụ ưa thích:</p>



<ul class="wp-block-list">
<li>Sổ làm việc hoặc bảng tính cung cấp các bộ vấn đề</li>



<li>Các công việc dựa trên máy tính</li>



<li>Hoạt động tương tác.</li>
</ul>



<h3 class="wp-block-heading">Thích nghi&nbsp;(làm và cảm nhận)</h3>



<p>Phong cách học tập phù hợp là “thực hành” và dựa vào trực giác hơn là logic.&nbsp;Những người này sử dụng phân tích của người khác và thích áp dụng cách tiếp cận thực tế, mang tính trải nghiệm.&nbsp;Họ bị thu hút bởi những thử thách và trải nghiệm mới cũng như việc thực hiện các kế hoạch.</p>



<p>Họ thường hành động theo bản năng “linh cảm” hơn là phân tích logic.&nbsp;Những người có phong cách học tập phù hợp sẽ có xu hướng dựa vào người khác để biết thông tin hơn là tự mình thực hiện phân tích.&nbsp;Phong cách học tập này phổ biến trong dân số nói chung.</p>



<p>Có một số kỹ thuật giảng dạy mà Người thích nghi ưa thích:</p>



<ul class="wp-block-list">
<li>Các hoạt động cho phép họ tham gia tích cực.</li>



<li>Sự hỗ trợ của người hướng dẫn và khám phá để đặt câu hỏi sâu hơn, chẳng hạn như “<em>điều gì sẽ xảy ra nếu?</em>” hoặc “<em>tại sao không?</em>”</li>



<li>Nhiệm vụ thúc đẩy khám phá độc lập.</li>
</ul>



<h2 class="wp-block-heading">Ý Nghĩa Giáo Dục</h2>



<p>Cả 2 giai đoạn học tập và chu trình của Kolb đều có thể được giáo viên sử dụng để đánh giá một cách nghiêm túc việc cung cấp dịch vụ học tập thường có cho học sinh và để phát triển các cơ hội học tập phù hợp hơn.</p>



<p>Các nhà giáo dục nên đảm bảo rằng các hoạt động được thiết kế và thực hiện theo cách mang lại cho mỗi người học cơ hội tham gia theo cách phù hợp nhất với họ.</p>



<p>Ngoài ra, các cá nhân có thể được giúp đỡ để học tập hiệu quả hơn bằng cách xác định các phong cách học tập mà họ ít ưa thích hơn và củng cố những phong cách này thông qua việc áp dụng chu trình học tập trải nghiệm.</p>



<p>Lý tưởng nhất là các hoạt động và tài liệu nên được phát triển theo cách phát huy khả năng từ từng giai đoạn của chu trình học tập trải nghiệm và đưa học sinh đi qua toàn bộ quá trình theo trình tự.</p>



<h2 class="wp-block-heading">Người Giới Thiệu</h2>



<ul class="wp-block-list">
<li>Kolb, DA (1976). Bản kiểm kê phong cách học tập: Sổ tay kỹ thuật . Boston, MA: McBer.</li>



<li>Kolb, DA (1981). Phong cách học tập và sự khác biệt về kỷ luật, trong: AW Chickering (Ed.) The Modern American College (trang 232–255). San Francisco, LA: Jossey-Bass.</li>



<li>Kolb, DA (1984). Học tập qua trải nghiệm: Trải nghiệm là nguồn gốc của học tập và phát triển (Tập 1). Vách đá Englewood, NJ: Prentice-Hall.</li>



<li>Kolb, DA, &amp; Fry, R. (1975). Hướng tới một lý thuyết ứng dụng về học tập trải nghiệm. Trong C. Cooper (Ed.), Nghiên cứu về quy trình nhóm (trang 33–57). New York: Wiley.</li>



<li>Kolb, DA, Rubin, IM, &amp; McIntyre, JM (1984). Tâm lý học tổ chức: các bài đọc về hành vi của con người trong các tổ chức . Vách đá Englewood, NJ: Prentice-Hall.</li>
</ul>
', 'Lý thuyết học tập trải nghiệm của Kolb hoạt động trên 2 cấp độ: chu trình học tập gồm 4 giai đoạn và 4 phong cách học tập riêng biệt. Tìm hiểu A-Z.', NULL, 'post', '2024-09-04 21:11:35', '2024-09-04 21:13:27');
