		<div class="elementor-element elementor-element-a032ee6 e-flex e-con-boxed e-con e-parent" data-id="a032ee6" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-c6b0705 e-flex e-con-boxed e-con e-child" data-id="c6b0705" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-74ce742 elementor-widget elementor-widget-text-editor" data-id="74ce742" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong>Trước cuộc họp này</strong></p><p>Khi kết thúc bước trước (Phần 4), bạn sẽ có:</p><p>▢ sườn điều hành!</p><p>▢ thu thập thông tin, số liệu vào báo cáo;</p><p>▢ đã có khoảnh khắc nhỏ để suy ngẫm cá nhân của riêng bạn.</p><p>▢ chuẩn bị giấy trắng hoặc một khoảng trống trên bảng trắng ảo với các câu hỏi phản ánh như giới hạn</p><ol><li>Mục đích là gì? </li><li>Điều gì đã thực sự xảy ra? </li><li>Chúng ta đã học được gì?</li><li>Chúng ta sẽ kể cho ai?</li></ol>								</div>
				</div>
				<div class="elementor-element elementor-element-4e50f1f elementor-widget elementor-widget-jet-accordion" data-id="4e50f1f" data-element_type="widget" data-widget_type="jet-accordion.default">
				<div class="elementor-widget-container">
							<div class="jet-accordion" data-settings="{&quot;collapsible&quot;:false,&quot;ajaxTemplate&quot;:false,&quot;switchScrolling&quot;:false,&quot;switchScrollingOffset&quot;:0,&quot;switchScrollingDelay&quot;:500}">
			<div class="jet-accordion__inner">
				<div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-8211" class="jet-toggle__control elementor-menu-anchor" data-toggle="1" role="button" tabindex="0" aria-controls="jet-toggle-content-8211" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Phần 5 - Thu thập kiến thức</div>							</div>
							<div id="jet-toggle-content-8211" class="jet-toggle__content" data-toggle="1" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Cuộc họp với người hướng dẫn/khách hàng kéo dài 1 giờ này được dành riêng để thu thập và chia sẻ những phản ánh cũng như phản hồi sau hội thảo. Nó bao gồm một khoảng thời gian để đánh giá cao, đánh giá sau hành động và bất kỳ bước tiếp theo nào có thể thực hiện được.</p><p><strong>NHIỆM VỤ</strong></p><ul><li>điều hành xưởng!</li><li>thu thập thông tin, số liệu vào báo cáo;</li><li>đã có chút thời gian để suy ngẫm cá nhân của riêng bạn.</li><li>Chuẩn bị giấy bảng trắng hoặc một khoảng trống trên bảng trắng ảo với các câu hỏi phản ánh.</li></ul></div>
							</div>
						</div><div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-8212" class="jet-toggle__control elementor-menu-anchor" data-toggle="2" role="button" tabindex="0" aria-controls="jet-toggle-content-8212" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Giới thiệu Mẫu kế hoạch hội thảo</div>							</div>
							<div id="jet-toggle-content-8212" class="jet-toggle__content" data-toggle="2" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Mẫu này giúp quá trình lập kế hoạch hội thảo trở nên dễ dàng hơn bằng cách trình bày rõ ràng từng bước cần thực hiện. Nó được chia thành 5 cuộc họp, mỗi cuộc kéo dài 1 giờ.</p><ul><li>Chia sẻ tầm nhìn</li><li>Xác định chương trình nghị sự</li><li>Tinh chỉnh chương trình nghị sự</li><li>Tóm tắt đội ngũ</li><li>Thu thập bài học.</li></ul></div>
