				<div class="elementor-widget-container">
									<p>Đến bây giờ bạn đã thiết lập được nghi thức khai mạc cho nhóm những người tổ chức hội thảo xuất sắc này. Bắt đầu bằng một vòng chia sẻ cá nhân, cũng có thể lấy chủ đề xoay quanh hội thảo (nhưng hãy giữ nó nhẹ nhàng và vui tươi, sẽ có thời gian để hồi tưởng sau!).</p><p>Ví dụ: sau một sự kiện quốc tế, bạn có thể hỏi &#8220;sau khi gặp những người tham gia từ khắp nơi trên thế giới, bạn muốn đến thăm quốc gia nào bây giờ và tại sao?&#8221;</p>								</div>
				</div>
					</div>
				</div>
					</div>
				</div>
