				<div class="elementor-widget-container">
									<p>Chạy phiên bản nhanh của Đánh giá sau hành động bằng cách yêu cầu người tham gia thêm ghi chú dán vào áp phích kèm theo các câu hỏi:</p><p>1. Mục đích là gì? <br />2. Điều gì thực sự đã xảy ra? <br />3. Chúng ta đã học được gì? <br />4. Chúng ta sẽ kể cho ai?</p><p>Cùng nhau xem xét và thảo luận những ghi chú đã thu thập được.</p><p>Bạn cũng có thể chọn các ý tưởng khác cho buổi hồi tưởng tại đây: <a href="https://huynhhieutravel.com/phuong-phap-hoi-tuong-flap/" target="_blank" rel="noopener">https://hocaz.net/phuong-phap-hoi-tuong-flap/</a></p>								</div>
