		<div class="elementor-element elementor-element-12e1f8d e-flex e-con-boxed e-con e-parent" data-id="12e1f8d" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-d917fa6 e-flex e-con-boxed e-con e-child" data-id="d917fa6" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-1d8b17a elementor-widget elementor-widget-text-editor" data-id="1d8b17a" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong>Trước cuộc họp này</strong></p><p>Khi kết thúc bước trước (Phần 3), bạn sẽ có:</p><p>▢ Xác nhận chương trình nghị sự cuối cùng với khách hàng của bạn.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-a935b0d elementor-widget elementor-widget-jet-accordion" data-id="a935b0d" data-element_type="widget" data-widget_type="jet-accordion.default">
				<div class="elementor-widget-container">
							<div class="jet-accordion" data-settings="{&quot;collapsible&quot;:false,&quot;ajaxTemplate&quot;:false,&quot;switchScrolling&quot;:false,&quot;switchScrollingOffset&quot;:0,&quot;switchScrollingDelay&quot;:500}">
			<div class="jet-accordion__inner">
				<div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-1771" class="jet-toggle__control elementor-menu-anchor" data-toggle="1" role="button" tabindex="0" aria-controls="jet-toggle-content-1771" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Phần 4 - Giới thiệu nhóm</div>							</div>
							<div id="jet-toggle-content-1771" class="jet-toggle__content" data-toggle="1" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Một buổi họp ngắn dành cho tất cả những người tham gia hội thảo trong tương lai để hiểu rõ và thống nhất về chương trình nghị sự, vai trò và trách nhiệm.</p><p><strong>NHIỆM VỤ</strong></p><ul><li>Xác nhận chương trình nghị luận cuối cùng dành cho khách hàng của bạn.</li><li>Đặt ngày cho cuộc gặp khách hàng/điều phối viên cuối cùng: Phần 5 &#8211; Thu thập kiến ​​thức</li></ul></div>
							</div>
						</div><div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-1772" class="jet-toggle__control elementor-menu-anchor" data-toggle="2" role="button" tabindex="0" aria-controls="jet-toggle-content-1772" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Giới thiệu Mẫu kế hoạch hội thảo</div>							</div>
							<div id="jet-toggle-content-1772" class="jet-toggle__content" data-toggle="2" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Mẫu này giúp quá trình lập kế hoạch hội thảo trở nên dễ dàng hơn bằng cách trình bày rõ ràng từng bước cần thực hiện. Nó được chia thành 5 cuộc họp, mỗi cuộc kéo dài 1 giờ.</p><ul><li>Chia sẻ tầm nhìn</li><li>Xác định chương trình nghị sự</li><li>Tinh chỉnh chương trình nghị sự</li><li>Tóm tắt đội ngũ</li><li>Thu thập bài học.</li></ul></div>
							</div>
						</div><div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-1773" class="jet-toggle__control elementor-menu-anchor" data-toggle="3" role="button" tabindex="0" aria-controls="jet-toggle-content-1773" aria-expanded="false" data-template-id="false">
