		<div class="elementor-element elementor-element-a75792a e-flex e-con-boxed e-con e-parent" data-id="a75792a" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-7dc938b e-flex e-con-boxed e-con e-child" data-id="7dc938b" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-6db25f6 elementor-widget elementor-widget-text-editor" data-id="6db25f6" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong>Trước cuộc họp này</strong></p><p>Khi kết thúc bước trước (Phần 2), bạn sẽ có:</p><p>▢ Soạn thảo chương trình nghị sự;</p><p>▢ Hãy chia sẻ nó với khách hàng của bạn để họ có thể chuẩn bị sẵn sàng tại hội thảo này.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-5be1949 elementor-widget elementor-widget-jet-accordion" data-id="5be1949" data-element_type="widget" data-widget_type="jet-accordion.default">
				<div class="elementor-widget-container">
							<div class="jet-accordion" data-settings="{&quot;collapsible&quot;:false,&quot;ajaxTemplate&quot;:false,&quot;switchScrolling&quot;:false,&quot;switchScrollingOffset&quot;:0,&quot;switchScrollingDelay&quot;:500}">
			<div class="jet-accordion__inner">
				<div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-9631" class="jet-toggle__control elementor-menu-anchor" data-toggle="1" role="button" tabindex="0" aria-controls="jet-toggle-content-9631" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Phần 3 - Tinh chỉnh chương trình nghị sự</div>							</div>
							<div id="jet-toggle-content-9631" class="jet-toggle__content" data-toggle="1" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Trong cuộc họp kéo dài 1 giờ này, khách hàng và người điều phối (và nhóm của họ) gặp nhau để thông qua chương trình nghị sự được đề xuất, đưa ra phản hồi và thực hiện bất kỳ thay đổi nào.</p><p><strong>NHIỆM VỤ</strong></p><ul><li>Soạn thảo chương trình nghị sự;</li><li>vui lòng chia sẻ nó với khách hàng của bạn để họ có thể chuẩn bị sẵn sàng tại cuộc thảo luận này;</li><li>gửi kịch bản cuối cùng/chương trình chi tiết;</li><li>ấn định ngày cho Phần 4 &#8211; Giới thiệu nhóm.</li></ul></div>
							</div>
						</div><div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-9632" class="jet-toggle__control elementor-menu-anchor" data-toggle="2" role="button" tabindex="0" aria-controls="jet-toggle-content-9632" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Giới thiệu Mẫu kế hoạch hội thảo</div>							</div>
							<div id="jet-toggle-content-9632" class="jet-toggle__content" data-toggle="2" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Mẫu này giúp quá trình lập kế hoạch hội thảo trở nên dễ dàng hơn bằng cách trình bày rõ ràng từng bước cần thực hiện. Nó được chia thành 5 cuộc họp, mỗi cuộc kéo dài 1 giờ.</p><ul><li>Chia sẻ tầm nhìn</li><li>Xác định chương trình nghị sự</li><li>Tinh chỉnh chương trình nghị sự</li><li>Tóm tắt đội ngũ</li><li>Thu thập bài học.</li></ul></div>
							</div>
