				<div class="elementor-widget-container">
									<p>Trên thực tế, bạn đang thành lập một nhóm làm việc tạm thời cho hội thảo nên thật tuyệt nếu tận dụng cơ hội này để cải thiện cách các bạn làm việc cùng nhau.</p>								</div>
