				<div class="elementor-element elementor-element-703f7d7 elementor-widget elementor-widget-text-editor" data-id="703f7d7" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong>Trước cuộc họp này</strong></p><p>Ở cuối bước trước (Phần 1), bạn đã có sẵn:</p><p>▢ đã thảo luận về tầm nhìn của hội thảo với khách hàng của bạn ở điểm trước;</p><p>▢ chia sẻ (có thể qua email) một bản ghi chú ý tưởng cho hội thảo;</p><p>▢ đã nhận được sự đồng ý cho ý tưởng đó và/hoặc một số phản hồi ban đầu.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-ce9893c elementor-widget elementor-widget-jet-accordion" data-id="ce9893c" data-element_type="widget" data-widget_type="jet-accordion.default">
