			<div class="jet-accordion__inner">
				<div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-2161" class="jet-toggle__control elementor-menu-anchor" data-toggle="1" role="button" tabindex="0" aria-controls="jet-toggle-content-2161" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Phần 2 - Soạn thảo chương trình nghị sự</div>							</div>
							<div id="jet-toggle-content-2161" class="jet-toggle__content" data-toggle="1" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Một cái nhìn có cấu trúc về cách đi từ khái niệm ban đầu đến chương trình nghị sự chi tiết cho hội thảo trong tương lai của bạn.</p><p><strong>NHIỆM VỤ</strong></p><ul><li>đã thảo luận về tầm nhìn của hội thảo với khách hàng ở điểm trước;</li><li>chia sẻ (có thể qua email) một bản ghi chú ý tưởng cho hội thảo;</li><li>đã nhận được sự đồng ý cho ý tưởng đó và/hoặc một số phản hồi ban đầu;</li><li>gửi dự thảo chương trình làm việc cho khách hàng;</li><li>ấn định ngày tổ chức hội thảo &#8220;Tinh chỉnh chương trình nghị sự&#8221; để thảo luận về vấn đề này.</li></ul></div>
							</div>
						</div><div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-2162" class="jet-toggle__control elementor-menu-anchor" data-toggle="2" role="button" tabindex="0" aria-controls="jet-toggle-content-2162" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Giới thiệu Mẫu kế hoạch hội thảo</div>							</div>
							<div id="jet-toggle-content-2162" class="jet-toggle__content" data-toggle="2" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p>Mẫu này giúp quá trình lập kế hoạch hội thảo trở nên dễ dàng hơn bằng cách trình bày rõ ràng từng bước cần thực hiện. Nó được chia thành 5 cuộc họp, mỗi cuộc kéo dài 1 giờ.</p><ul><li>Chia sẻ tầm nhìn</li><li>Xác định chương trình nghị sự</li><li>Tinh chỉnh chương trình nghị sự</li><li>Tóm tắt đội ngũ</li><li>Thu thập bài học.</li></ul></div>
