									<p>Bạn tưởng tượng mọi người cảm thấy và hành xử như thế nào sau sự kiện này? Mời mỗi người xem xét những gì sẽ là kết quả đầu ra phi vật chất, cảm xúc, “mềm” và ghi chú riêng vào giấy dán. Hãy nhóm chúng lại và thảo luận.</p>								</div>
