		<div class="elementor-element elementor-element-87e295b e-flex e-con-boxed e-con e-parent" data-id="87e295b" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-7ea33be e-flex e-con-boxed e-con e-child" data-id="7ea33be" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-07d24ff elementor-widget elementor-widget-jet-accordion" data-id="07d24ff" data-element_type="widget" data-widget_type="jet-accordion.default">
				<div class="elementor-widget-container">
							<div class="jet-accordion" data-settings="{&quot;collapsible&quot;:false,&quot;ajaxTemplate&quot;:false,&quot;switchScrolling&quot;:false,&quot;switchScrollingOffset&quot;:0,&quot;switchScrollingDelay&quot;:500}">
			<div class="jet-accordion__inner">
				<div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-8201" class="jet-toggle__control elementor-menu-anchor" data-toggle="1" role="button" tabindex="0" aria-controls="jet-toggle-content-8201" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">Giới thiệu Mẫu kế hoạch hội thảo</div>							</div>
							<div id="jet-toggle-content-8201" class="jet-toggle__content" data-toggle="1" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p><strong>Mục tiêu</strong></p><ul><li>Tạo tiền đề cho sự hợp tác tuyệt vời với khách hàng.</li><li>Xác định mục tiêu và ý định chính của buổi hội thảo.</li><li>Soạn thảo và cấu trúc một chương trình nghị sự .</li><li>Tinh chỉnh chương trình nghị sự được đề xuất với khách hàng, nhóm và diễn giả.</li><li>Cải thiện sự rõ ràng, hiểu biết lẫn nhau và luồng giao tiếp.</li><li>Cùng theo dõi và học hỏi nhé.</li></ul><p><strong>Khi nào phiên họp này sẽ được thực hiện?</strong></p><p>Nếu bạn đang tạo một hội thảo mới, rất có thể bạn đang làm việc đó cho khách hàng. Trong toàn bộ quá trình, bạn sẽ liên hệ với họ để tìm hiểu về nhu cầu của họ, thống nhất về thiết kế, thu thập phản hồi và cùng nhau suy ngẫm sau sự kiện.</p><p>Mẫu này làm cho quá trình đó trở nên dễ dàng hơn bằng cách trình bày rõ ràng từng bước cần thực hiện. Nó được chia thành 5 phần, mỗi phần kéo dài 1 giờ.</p><ol><li>Chia sẻ tầm nhìn</li><li>Xác định chương trình nghị sự</li><li>Tinh chỉnh chương trình nghị sự</li><li>Tóm tắt đội ngũ</li><li>Thu thập bài học</li></ol><p>Phần đầu tiên, Chia sẻ tầm nhìn, đưa ra mô hình cho cuộc gặp đầu tiên với khách hàng của bạn (và/hoặc nhóm của họ) để thu thập thông tin về hội thảo trong tương lai. Có yếu tố không thể thương lượng nào không (ví dụ: ngày đã được ấn định chưa)? Kết quả mong muốn hữu hình và vô hình là gì? Bạn thậm chí có thể tải xuống bản vẽ sẵn để sử dụng cho cuộc gặp đầu tiên quan trọng này!</p><p>Phần thứ hai, Xác định chương trình nghị sự có thể là… một cuộc họp với chính bạn, nếu bạn làm việc một mình, hoặc chỉ với người đồng điều phối của bạn. Đây là giai đoạn mà bạn sẽ xác định dự thảo chương trình làm việc của mình để chia sẻ với khách hàng trước hoặc tại cuộc họp tiếp theo.</p><p>Phần thứ ba, Tinh chỉnh chương trình làm việc, là giải thích thiết kế được đề xuất của bạn và thu thập phản hồi. Đây cũng là cơ hội để bạn chia sẻ kiến ​​thức về hỗ trợ và giải thích các lựa chọn của mình, giúp bạn và khách hàng cùng nhau phát triển. Khi ngày hội thảo đến gần, hãy chuẩn bị sẵn sàng bằng cách thông báo tóm tắt cho nhóm , người chủ trì và diễn giả trong cuộc họp thứ ba. Cuối cùng, sau khi sự kiện kết thúc, hãy cùng nhau ôn lại một lần nữa tập trung vào việc học tập. Các điểm tiếp xúc được nêu chi tiết trong tài nguyên này không bao gồm toàn bộ quá trình lập kế hoạch hội thảo. Các phần được bao gồm trong mẫu là những phần có nhiều khả năng xảy ra nhất trong các cuộc họp đồng bộ.</p><p>Có những nhiệm vụ khác, chẳng hạn như ký thỏa thuận với khách hàng của bạn, quảng cáo hội thảo hoặc đăng ký người tham gia, diễn ra không đồng bộ, qua email và các công cụ kỹ thuật số khác. Tất cả các bước này được mô tả trong bài đăng blog kèm theo về Lập kế hoạch hội thảo .</p><p><strong>Ai có thể tạo điều kiện cho nó?</strong></p><p>Tiền đề cho chuỗi cuộc họp này là bạn có một hội thảo để tổ chức và điều hành. Nếu bạn không làm việc cho khách hàng nhưng đã tự lên ý tưởng cho hội thảo và phục vụ trực tiếp cho người tham gia, bạn vẫn có thể sử dụng mẫu này làm bản phác thảo cho những vấn đề bạn cần làm rõ khi thiết kế.</p><p>Ngày càng có nhiều khả năng bạn sẽ tổ chức các cuộc họp này trực tuyến, trong không gian họp ảo như Zoom hoặc Teams. Bảng trắng hoặc tài liệu được chia sẻ rất hữu ích, đặc biệt là trong phiên đầu tiên và bạn có thể tải xuống khung vẽ sẵn sàng sử dụng của chúng tôi để bắt đầu!</p></div>
							</div>
						</div>			</div>
		</div>
						</div>
				</div>
					</div>
				</div>
					</div>
				</div>
