				<div class="elementor-element elementor-element-9215fc5 elementor-widget elementor-widget-text-editor" data-id="9215fc5" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong>Kiểm tra người dùng</strong></p><p>Bạn sẽ có 5 cuộc phỏng vấn trong những giờ tiếp theo và giữa giờ nghỉ trưa. Phân bổ 45-60 phút cho mỗi bài kiểm tra của người dùng.</p>								</div>
				</div>
					</div>
				</div>
		<div class="elementor-element elementor-element-24433c0 e-flex e-con-boxed e-con e-child" data-id="24433c0" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-32db610 elementor-widget elementor-widget-text-editor" data-id="32db610" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Ghi chú khi bạn xem. Viết ra những trích dẫn, quan sát và giải thích trực tiếp. Cho biết tích cực hay tiêu cực.</p><p>Sử dụng hai màu khác nhau của ghi chú post-it, một trong những màu tích cực (ví dụ: ghi chú post-it màu xanh lá cây) và tiêu cực (ví dụ: màu cam).</p><p>Sau mỗi cuộc phỏng vấn, hãy dán các ghi chú sau cuộc phỏng vấn của bạn vào phần thích hợp trong lưới cuộc phỏng vấn của bạn. Thảo luận ngắn gọn về cuộc phỏng vấn nhưng chờ đợi để đưa ra kết luận.</p>								</div>
				</div>
					</div>
				</div>
					</div>
				</div>
