									<p>Đến cuối ngày thứ 2, tất cả việc ra quyết định đã hoàn tất và các chuyên gia của bạn có thể nghỉ hưu và tiếp tục công việc hàng ngày của họ. Bạn đã có định hướng rõ ràng và có thể chuyển sang tạo mẫu và thử nghiệm những gì họ yêu cầu bạn.</p>								</div>
				</div>
