									<p><a href="https://huynhhieutravel.com/gioi-thieu-va-bao-tang-nghe-thuat-sprint-2/" target="_blank" rel="noopener"><strong>Bảo tàng nghệ thuật</strong></a></p><p>Tiết lộ các khái niệm (được vẽ ngày hôm qua) cho nhóm.</p>								</div>
