				<div class="elementor-element elementor-element-8fb8ac4 elementor-widget elementor-widget-text-editor" data-id="8fb8ac4" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><a href="https://huynhhieutravel.com/luong-nguoi-dung-sprint-2/" target="_blank" rel="noopener"><strong>Luồng thử nghiệm người dùng</strong></a></p><p>Bạn sẽ sử dụng bảng phân cảnh để đi từ ý tưởng chiến thắng đến nguyên mẫu của mình. Để đẩy nhanh quá trình, mọi người viết một phiên bản cơ bản của bảng phân cảnh của riêng họ (Quy trình kiểm tra người dùng) và sau đó nhóm bỏ phiếu xem phiên bản nào sẽ được tạo bảng phân cảnh và tạo nguyên mẫu.</p><p>Mặc dù đó là một bước bổ sung nhưng nó tăng tốc quá trình xây dựng kịch bản phân cảnh lên hàng triệu dặm và loại bỏ khía cạnh “do ủy ban thiết kế” của nó.</p>								</div>
				</div>
					</div>
				</div>
		<div class="elementor-element elementor-element-9e68492 e-flex e-con-boxed e-con e-child" data-id="9e68492" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-f1611fc elementor-widget elementor-widget-text-editor" data-id="f1611fc" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Vì các khái niệm chiến thắng thường không được vẽ theo cốt truyện tuyến tính, hãy tập trung vào nhóm để tạo cơ sở cho việc lập bảng phân cảnh bằng loại bài tập ghi chú và bình chọn này:</p><ol><li><b>Mọi người</b> trong nhóm <b>viết ra một quy trình gồm 6 bước với các bước hành động</b> (các lần nhấp, chạm, chuyển động riêng lẻ mà người dùng của bạn sẽ thực hiện để chuyển sang cảnh tiếp theo của bảng phân cảnh). Mỗi bước hành động nên có một ghi chú sau đó. <i>Mẹo: Viết ra bước hành động đầu tiên và cuối cùng rồi điền vào chỗ trống. (Nhìn vào bản đồ của bạn và các câu hỏi chạy nước rút!</i> ). &#8211; 8 phút</li><li>Mỗi người <b>đọc to 6 bước hành động của mình khi xếp chúng lên bảng theo hàng</b>. (1 phút cho mỗi người). Người quyết định nên đi đầu tiên hoặc cuối cùng (để có thể nghe thấy tất cả các luồng kiểm tra khác).</li><li>Sau khi mọi người đã sắp xếp xong luồng của mình, <b>mỗi thành viên trong nhóm sẽ nhận được một dấu chấm biểu quyết và Người quyết định nhận được hai dấu chấm biểu quyết. Cho 5 phút để bình chọn</b>. Họ nên chọn một hàng trong luồng người dùng mà họ cho là nền tảng tốt cho nguyên mẫu. Đối với Người quyết định, một phiếu bầu sẽ xác nhận luồng cơ sở và phiếu còn lại có thể được sử dụng để đánh dấu một bước hành động trong các luồng người dùng khác mà sẽ thú vị để đưa vào luồng thử nghiệm chính. Khoanh tròn dòng chiến thắng.</li><li>Đặt các ghi chú sau đó (các bước hành động) của <b>người chiến thắng vào các ô trống của bảng phân cảnh 8 màn hình</b>.</li></ol>								</div>
				</div>
					</div>
				</div>
					</div>
				</div>
		<div class="elementor-element elementor-element-6512581 e-flex e-con-boxed e-con e-child" data-id="6512581" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
