		', 'Quyết định: Bình chọn giải pháp 10:00 10 phút Giới thiệu về Ngày thứ 2 Sáng ngày 2 được dành để quyết định nên tạo nguyên mẫu cái gì và buổi chiều là để tạo bảng phân cảnh để hướng dẫn việc tạo nguyên mẫu. Đến cuối ngày thứ 2, tất cả việc ra quyết [&hellip;]', NULL, 'post', '2024-06-27 17:59:50', '2024-06-27 18:42:56');